programs.sol:
"""A partial lexical-association model, not a general semantic detector.

It recognizes a few readable phrase families: document metadata, chat
boundaries, source-code paths, and fixed institutional/technical names.
Each response is emitted on the token that finishes the listed text.
Other text is near zero. Document starts have a negative baseline.
"""
READS = ()

# Negative responses at the second word of familiar compound names.
COMPOUND_NAMES = {
    'International Space': -3.6,
    'Massachusetts Institute': -3.6,
    'Major League': -2.25,
    'Royal College': -2.8,
    'Amazon Web': -4.3,
    'Simple Storage': -2.7,
    'World Trade': -1.6,
}

# Code identifiers and namespace/path fragments, as actually tokenized.
CODE_ENDINGS = {
    'HTTP/': -3.2,
    'node_modules': -0.7,
    'tsconfig': -1.4,
    'Content-Type': -0.7,
    'go.mod': 0.65,
    '.git/': 1.1,
    'laravel/framework': 2.9,
    'go-playground/validator': 4.2,
    'scrapy/sp': 1.7,
    'kivy.u': 6.0,
    'cn.b': 2.5,
    'cn.bmob': 4.0,
    'cn.bmob.v': 3.0,
}

MARKERS = {
    '</tool_response>': 0.65,
    '<tool_response>': 0.33,
    '<tool_call>': -0.35,
    '</tool_call>': -0.45,
    '<|im_start|>': 0.18,
    '<|im_end|>': 0.17,
}
DECLARATIONS = {'import', 'package', 'using', '#include', 'def', 'const'}
SENIOR_ROLES = {'Director', 'Senior Manager', 'Math Expert'}
EXECUTIVE_ROLES = {'CEO', 'SVP', 'GMAT Club Legend', 'BSchool Forum Moderator'}


def finishes(text, token, phrase):
    """Do not trigger when a longer, unrelated token merely shares a suffix."""
    before = text[:-len(phrase)]
    return (text.endswith(phrase) and len(token) <= len(phrase)
            and not (before and before[-1].isalpha()))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        old, position = '', 0
    else:
        _, old, position = carry
    text = old + token
    value = MARKERS.get(token, 0.0)
    if position == 0:
        value = -1.2 if token in DECLARATIONS else -0.25
        if token == 'Title':
            value = -1.49
        elif token == '<|im_start|>':
            value = -0.38
    elif position == 1 and old == 'Title' and token == ':':
        value = 7.57
    else:
        for phrase, response in COMPOUND_NAMES.items():
            if finishes(text, token, phrase):
                value = response
        for phrase, response in CODE_ENDINGS.items():
            if finishes(text, token, phrase):
                value = response
        if token == '/bin' and old.endswith('#!/usr'):
            value = -5.3
        if finishes(text, token, 'World War') and not old.endswith('Second World'):
            value = -1.65
        if finishes(text, token, 'administrative territorial'):
            value = 1.0
        if token == '+' and old.endswith('UTC'):
            value = -2.4
        if token == '-CN' and old.endswith(('zh', 'zh-Hans')):
            value = 1.1
        if token == ' HOLDERS' and old.endswith('COPYRIGHT'):
            value = 5.7
        if token == 'Joined' and old.endswith('\n'):
            role = old.rstrip('\n').split('\n')[-1].strip()
            if role in SENIOR_ROLES:
                value = 3.0
            elif role in EXECUTIVE_ROLES:
                value = 4.0
    return (doc, text[-120:], position + 1), value

programs.haiku:
"""Doc-start negative plus small positive for dotted/slashed code and URL fragments."""
READS = ()

def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[t]
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, -0.3
    if cur[:1] in "./=" and cur[1:2].isalpha():
        return None, 0.07
    return None, 0.0

programs.sol:
"""Predict a mostly negative response to declaration-introducing syntax.

Line-initial def/function/fn/func and void after access modifiers are the main
cases. Indentation, assignment and callbacks weaken the response; export and
private declarations strengthen it. Outside declarations, def/Def spelling
fragments instead receive a positive value. Smaller rules recognize other
kinds of definitions and a few formatting patterns. Everything else is zero.
Only a bounded recent text buffer is kept, reset at document boundaries.
"""
import re

READS = ()

# These are declaration words and the token forms used by the syntax rules.
KEYWORDS = {
    'def', 'ndef', 'Def', '_def', '.def', 'function', '(function',
    '=function', ':function', 'fn', 'func', 'void', 'package', 'var',
    'module', 'command', '{\\', 'df', 'table', 'TABLE', 'frames', '(',
    'theorem', 'procedure', 'PROC', 'FIG', 'import', 'ref',
    'EDURE', 'routine',
}


def response(token, history):
    word = token.strip()
    if '\\begin{' in history[-40:]:
        environments = r'\\begin\{(?:theorem|lemma|proposition|corollary|definition)$'
        if re.search(environments, history + token):
            return -3.6
    if word and len(word) > 1 and not word.strip('·'):
        return 1.26 if history.endswith('····') else 0.0
    if word not in KEYWORDS:
        return 0.0
    # Treat escaped source-code newlines as line breaks too.
    text = history.replace('\\n', '\n').replace('\\t', '\t')
    line = text.rsplit('\n', 1)[-1].rstrip('\r').replace('\xa0', ' ')
    start = not line.strip(' \t\r0123456789:+-`')
    match = re.search(r'([A-Za-z_]+)\s*$', line)
    previous = match.group(1) if match else ''

    if word in {'Def', '_def', '.def'}:
        return 1.7
    if word == 'ndef' and history.endswith('\\'):
        return -3.6
    if word == 'def':
        if previous == 'async':
            return -5.0
        if line.strip() == '#':
            return -3.8
        if start:
            # Proof documents also contain words beginning with "def".
            if re.search(r'\b(?:theorem|lemma)\b|⊢', text):
                return -0.5
            if token.startswith('\t'):
                return -1.7
            if token.startswith(' '):
                return -2.9
            if not history:
                return -4.6
            return -6.9 if text.endswith('\n\n') else -5.8
        return 1.6
    if word in {'function', '(function', '=function', ':function'}:
        if previous in {'async', 'export'}:
            return -9.5 if line.strip() in {'async', 'export'} else -5.0
        if previous == 'public':
            return -3.7
        if previous in {'private', 'protected'}:
            return -7.0
        if history.rstrip().endswith('=') or word == '=function':
            return -3.0
        if start and word == 'function':
            if not history:
                return -4.9
            return -5.4 if token.startswith(' ') else -7.1
        if token == 'function' and history.rstrip().endswith(('}', ';')):
            return -7.5  # named functions in compact JavaScript
        if history.rstrip().endswith((':', ',', '(')) or word != 'function':
            return -1.4
        return -0.8 if token == 'function' else 0.0
    if word in {'fn', 'func'} and re.fullmatch(r'\s*\d+:', line):
        return -1.0  # declarations quoted in line-numbered search results
    if word == 'fn':
        if re.search(r'\bpub(?:\([^)]*\))?\s*$', line):
            return -5.4
        if previous in {'async', 'unsafe'}:
            return -4.5
        if start:
            if token[:1].isspace():
                return -3.8
            return -3.3 if history.endswith('\\n') else -5.5
    if word == 'func':
        if start:
            if token[:1].isspace():
                return -2.6
            return -6.0 if history.endswith('\n\n') else -4.4
        if previous in {'private', 'public', 'static'}:
            return -4.0
        return -1.1 if token != word or line.endswith(':') else 0.0
    if word == 'void':
        if re.search(r'\bprivate\b', line):
            return -7.0
        if previous == 'static':
            return -5.6
        if previous in {'public', 'protected', 'virtual'}:
            return -3.4
        if previous == 'override':
            return -4.5
        if previous.lower().endswith('inline'):
            return -3.8
        if start:
            return -2.8 if token[:1].isspace() else -3.3
        if line.endswith(':'):
            return -1.5
    if not history and word in {'package', 'var', 'module'}:
        return 4.2
    if word == 'command' and (not history or re.search(r'\\(?:re)?new$', history)):
        return -5.5
    if token == '{\\' and re.search(r'\\(?:re)?newcommand\*?$', history):
        return -7.4
    if word == 'df' and history.endswith('\xa0'):
        return -2.5  # definition labels in Metamath references
    if word.lower() == 'table' and previous.lower() == 'create':
        return -3.2
    if word in {'PROC', 'EDURE'} and re.search(r'\bCREATE\b', line):
        return -4.5
    if word == 'frames' and history.endswith('@key'):
        return -3.0
    if word == '(' and history.endswith('(define'):
        return -10.0
    if word == 'routine' and previous == 'sub':
        return -4.5
    if word == 'ref' and history.endswith('\\eq'):
        return 3.6
    if word == 'theorem' and start:
        return -2.5
    if word.lower() == 'procedure' and start:
        return -3.6
    if word == 'FIG':
        return -0.4
    if word == 'import' and token.startswith(' '):
        return -0.27
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, history)
    return (doc, (history + token)[-512:]), value

programs.haiku:
"""Function-definition keyword detector for layers.1.mlp.down_proj:2242.

The component goes strongly negative on the keyword that opens a named function,
method or procedure in source code: `function`, `def`, `fn`, `func`, `procedure`,
and `void` used as a return type (`private void Foo()`). It is most negative when
the keyword starts a line (after indentation) or follows an access modifier such as
`public`, `private`, `static` or `export`, or an `=` (JavaScript function expressions).
The same words in ordinary prose (`a function of x`, `the void`) give nothing, and
the component also weakly responds to `create table` and Metamath-style `df` / `theorem`
lines. Everywhere else it predicts 0.
"""

READS = ()

# Declaration keywords and their typical strength when they open a definition.
DEFINERS = {
    "function": -5.0,
    "def": -4.0,
    "fn": -4.5,
    "func": -4.5,
    "procedure": -4.5,
    "void": -3.5,
}
MODIFIERS = {"public", "private", "protected", "static", "export", "async", "pub", "final"}
PROSE_WORDS = {"a", "an", "the", "of", "is", "was", "be", "to", "and", "or", "in", "for", "this"}


def _prev_context(prefix):
    """The previous token, and whether it is a line start or a declaration cue."""
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return "", True
    prev_raw = prefix.token_strings[-2]
    prev = prev_raw.strip()
    line_start = "\n" in prev_raw or (prev_raw.strip() == "" and prev_raw != "")
    cue = prev in MODIFIERS or prev in ("=", "{", "}", ";") or line_start
    return prev, cue


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    prev, cue = _prev_context(prefix)
    value = 0.0
    if word in DEFINERS:
        if prev in PROSE_WORDS:
            value = 0.0
        elif cue:
            value = DEFINERS[word]
        else:
            value = DEFINERS[word] * 0.2
    elif word == "theorem":
        value = -2.0 if cue else 0.0
    elif word == "df" and cue:
        value = -2.4
    elif word == "table" and prev == "create":
        value = -4.0
    return carry, float(value)

programs.sol:
"""Spelling-sensitive pulses for tax and short t-initial syllables.

Tax and its inflections, including split t + ax, are strongly positive.
Short ar/ap fragments following t also fire; longer preceding fragments
weaken this response. Greek tau-eta and its article endings are negative.
Small corrections cover accented vowels, Arabic letters, Japanese vowel
lengthening after ta, and repeated middle dots. Other positions default to zero.
This is not a general taxation-topic detector.
"""
import re
import unicodedata as ud
from anyascii import anyascii

READS = ()
TAX_ENDINGS = {'': 5.2, 'es': 6.7, 'ed': 3.6, 'ation': 2.7, 'able': 2.1}


def plain(text):
    return ''.join(c for c in ud.normalize('NFD', text.lower())
                   if not ud.combining(c))


def onset_strength(previous):
    """Favor isolated t, short capitals, and the not-/art- spellings."""
    stem = previous.strip(' \t\n._-/(').lower()
    if not stem.isascii():
        return 0.8 if len(stem) <= 3 else 0.12
    if (stem in ('t', 'not') or
        (len(stem) <= 4 and 'art' in stem) or
        (previous.strip().isupper() and len(stem) <= 4)):
        return 1.2
    return 0.4 if len(stem) <= 3 else 0.12


def rhyme_pulse(tail):
    """Different short rhymes of a t syllable have different strengths."""
    if tail == 'ar':
        return 5.0
    if tail.startswith('arr'):
        return 6.0 if len(tail) <= 3 else 2.0
    if tail.startswith('ar') and len(tail) <= 5:
        weight = {'i': 3.8, 's': 2.8, 'a': 2.0, 'y': 1.5,
                  'd': 1.6, 'o': 3.0, 'e': 0.7}.get(tail[2:3], 1.1)
        return weight * 0.5 ** (len(tail) - 3)
    if tail in ('ap', 'aps', 'apped', 'apping'):
        return 2.0 if tail == 'ap' else 3.0
    if tail == 'ash':
        return 2.4
    if tail == 'ort':
        return 2.5
    if tail in ('an', 'ans', 'ango', 'aw', 'ale', 'ame', 'oll'):
        return 0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    low = token.lower()
    if token and all('CYRILLIC' in ud.name(c, '') for c in token):
        low = anyascii(token).lower()
    word = low.lstrip(' \t\n._-/(')
    prior, current = plain(history), plain(token)
    after_t = prior.endswith(('t', 'τ', 'т', 'ت'))
    continuation = bool(token) and not token[0].isspace()

    # The tax stem and split spellings which complete it.
    tax, split = word, False
    if continuation and prior.endswith('t') and low.startswith('ax'):
        tax, split = 't' + low, True
    elif continuation and prior.endswith('ta') and low.startswith('x'):
        tax, split = 'ta' + low, True
    value = 0.0
    if tax.startswith('tax') and tax[3:] in TAX_ENDINGS:
        value = TAX_ENDINGS[tax[3:]]
        if split:
            value += 2.7
        elif low.startswith('-'):
            value += 4.0
        elif low.startswith('_'):
            value += 1.0
        if re.search(r'(income|sales|export|corporate|after|pre)$', prior):
            value += 1.7
    if token == '税':
        value = 6.7

    # Syllables within a token, or completed by a following fragment.
    tail, strength = '', 0.0
    if continuation and after_t and not prior.endswith('st'):
        tail, strength = low, onset_strength(previous)
    elif word.startswith('t'):
        tail, strength = word[1:], 0.63
    elif word.startswith('ata'):
        tail = word[2:]
        strength = 0.1 if token.strip().isupper() else 0.54
    elif word.startswith('ita'):
        tail, strength = word[2:], 0.22
    if after_t and tail.startswith('ata'):
        tail, strength = tail[2:], 1.6
    if value == 0.0:
        value = rhyme_pulse(tail) * strength

    # Cross-script continuations; Greek article fragments are strongly negative.
    if continuation and after_t:
        if current in ('η', 'ηι'):
            value = -4.5
        elif current == 'ε':
            value = -1.0
        elif current == 'α':
            value = 0.35
        elif token == 'ح':
            value = -4.2
        elif len(token) == 1 and 'ARABIC' in ud.name(token, ''):
            value = -3.0 if ud.combining(token) else -1.2
        elif len(token) == 1 and 'LATIN' in ud.name(token, ''):
            name = ud.name(token, '')
            marked_vowel = current in 'aeiouy' and current != low
            if marked_vowel and (current in 'uy' or
                                 'DIAERESIS' in name or 'CARON' in name):
                value = -1.0
    if current in ('ν', 'ς') and prior.endswith('τη'):
        value = -4.0
    if current == 'η' and prior.endswith('θ'):
        value = -1.8
    if token.startswith('ー') and history.endswith('タ'):
        value = 2.6
    if token == 'ξ' and prior.endswith('τα'):
        value = 4.5
    if len(token) > 1 and set(token) == {'·'}:
        value = -0.55
    return (doc, (history + token)[-24:], token), value

"""A directed feeling or mental relationship, not positive versus negative mood.

The main response is negative on emotional/mental verbs and, more strongly,
on the preposition introducing their object: 'interested in', 'familiar with',
'passion for'. Possessor 'of' after attention/faith/interest instead gets a
positive response. Weaker relation/direction words get smaller responses.
Nearby complete words supply context; documents reset it. English inflections
use WordNet's dictionary, and a few Chinese/Russian equivalents are included.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

FEEL = set('''love hate adore cherish prefer enjoy appreciate fear dislike
    detest admire resent envy worship favour favor embrace'''.split())
KNOW = set('''know understand believe learn recognize realize comprehend
    perceive remember forget read'''.split())
STANCE = set('''agree disagree support oppose reject accept approve disapprove
    respect value trust distrust avoid choose follow recommend'''.split())
SUBJECTS = set('i we he she they you who'.split())
DEGREE = set('''really absolutely truly especially particularly simply always
    never even still also not t'''.split())

FAMILIAR = set('familiar familiarity unfamiliar acquainted acquaintance'.split())
BELIEF = set('believe belief confidence confident faith trust'.split())
KNOWLEDGE = set('''knowledge understanding awareness aware perception ignorance
    ignorant grasp mastery misunderstanding'''.split())
INTEREST = set('interest interested disinterest'.split())
INTENSE = set('''passion appreciation gratitude admiration affection hatred
    attitude enthusiasm passionate enthusiastic excitement
    penchant frustration discontent'''.split())
AFFECTED = set('''fascinated fascination impressed amused amazed
    astonished persuaded obsessed obsession attracted attraction drawn'''.split())
OWNER = set('''confidence faith interest allegiance concern mind attention
    prayer freedom personality'''.split())
LINK = set('''access connection relationship relation exposure attachment
    commitment committed dedication dedicated loyalty loyal adherence adhere
    sensitive sensitivity open opposed opposition objection resistant resistance
    attention approach perspective view opinion recognition criticism critique
    ownership possession acceptance sense study review discussion overview
    information care curious curiosity worried anxious excited hungry appetite
    talent skilled participation participate involved involvement invest invested
    investment delight pleasure rejoice trouble problem satisfaction pleased
    satisfied comfortable delighted happy affair benefit suffer suffering
    protect protection contact interact engage focus rely insist reflect
    control subscribe'''.split())
PREPOSITIONS = set('of to with in for about on from at by over into toward towards'.split())

@lru_cache(maxsize=20000)
def forms(word):
    return set(wordnet.base_forms(word)) | {word}


def predict_text(tail, token):
    w = token.strip().lower()
    m = re.search(r'([A-Za-z]+)[ \t]*$', tail)
    prev = m.group(1).lower() if m else ''
    f = forms(prev)
    if w in PREPOSITIONS:
        if w == 'of' and f & (OWNER | {'attitude'}):
            return 1.04
        if w == 'with' and f & FAMILIAR:
            return -4.05
        if w == 'in' and f & BELIEF:
            return -3.76
        # Affinity and gratitude have their own conventional complements.
        if w == 'of' and f & {'fond', 'fan'}:
            return -4.1
        if w == 'for' and f & {'grateful', 'thankful'}:
            return -3.6
        if w == 'with' and f & {'comfortable'}:
            return -3.2
        if w == 'of' and f & KNOWLEDGE:
            return -2.64
        if w == 'in' and f & INTEREST and prev != 'interesting':
            return -3.1
        if prev in {'away', 'back', 'return', 'forward'}:
            if (prev == 'away' and w == 'from') or (prev != 'away' and w == 'to'):
                return -0.92
            return 0.0
        if w == 'about' and f & {'curious', 'curiosity', 'excited', 'excitement'}:
            return -2.59
        if f & INTENSE and w in {'for', 'of', 'about', 'with', 'toward', 'towards'}:
            return -6.02 if w == 'for' else -3.66
        # 'Feeling of' describes a sensation, not its directed target.
        if prev in {'feeling', 'feelings'} and w in {'of', 'with'}:
            return 0.25
        if prev in {'love', 'feeling', 'feelings'} and w in {
            'of', 'with', 'for', 'toward', 'towards'
        }:
            return -4.25 if w in {'for','toward','towards'} else -2.24
        if f & AFFECTED and w in {'to', 'with', 'by'}:
            return -2.99
        if prev not in {'related', 'connected', 'attached', 'associated',
                        'depending', 'depends', 'responsible'} and f & LINK:
            return -0.54
        if w == 'about':
            return -0.41
        if w in {'toward', 'towards'}:
            return -0.61
        return 0.05 if w == 'at' else 0.0
    if re.fullmatch('[A-Za-z]+', w):
        m = re.search('[A-Za-z]+$', tail + token)
        f = forms(m.group().lower() if m else w)
        personal = prev in SUBJECTS | DEGREE
        if w == 'like':
            return -2.27 if personal or prev in {'to', 'will'} else -0.06
        if f & FEEL or f & {'like'}:
            return -2.16 if personal else -0.81
        if f & KNOW:
            return -0.32
        if f & {'value'} and prev in SUBJECTS:
            return -4.24
        if f & {'view', 'perspective', 'opinion', 'approach'}:
            return -0.26
        if f & STANCE:
            return -0.25
        if w == 'without':
            return 0.33
        if w in {'anti', 'against'}:
            return -0.35
    if w.endswith(('对', '對', '对于', '對於')):
        return -0.85
    if w in {'喜欢', '喜歡', '爱', '愛', '热爱', '了解', '认为', '認為',
             '关注', '關注', '反对', '反對'}:
        return -0.92
    if token[:1].isspace():
        if w == 'к':
            return -0.29
        if w == 'о':
            return -0.51
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (tail + token)[-64:]), predict_text(tail, token)

"""A mixed boundary and token-form feature, not a sentence-level classifier.

Predict negative document starts/end markers; positive spaces before line
