        value = 0.18 if text.startswith(' ') else 0.50
    elif any(c.isalpha() and ord(c) > 127 and
             'LATIN' in unicodedata.name(c, '') for c in word):
        value = 0.10
        if len(word) == 1:
            name = unicodedata.name(word, '')
            value = 0.30
            if 'CIRCUMFLEX' in name:
                value = 0.50
            elif 'ACUTE' in name:
                value = 0.42
            elif 'GRAVE' in name:
                value = 0.11
    return doc, value

programs.haiku:
"""Predicts layers.1.mlp.down_proj:2247, a component of layer 1's MLP output.

What it does, in plain terms: it fires on the word that *follows* a small set of cue words,
where the next token is very predictable. Its strongest responses are in code and URLs:
- the first piece of a library or domain name right after `import`, `package` or `#include`
  ("import org", "package com", `#include "`), i.e. the start of a dotted name;
- the "://" after "http"/"https", the "www" after that, and the ".util" of "java.util" and
  the ".com" of "github.com".
It responds moderately to spoken openers: a contraction after a subject pronoun ("it's",
"I'm", "Here's"), "let me", a subject plus an auxiliary ("it is", "I think"), a discourse word
before a comma ("Yes,", "However,"), common stock phrases ("how to", "thank you", "one of"),
"return", and the "(" of "if (" / "for (". Everywhere else it is near 0.

The numbers are rough averages in activation units, fitted on training text: "org" after
"import" is about 8, a URL "://" about 5.5, a contraction after a pronoun about 2, most
spoken openers about 1.
"""

READS = ()

# Words that introduce a module path, a URL or a header name.
IMPORT_WORDS = {"import", "package", "#include"}
URL_SCHEMES = {"http", "https"}
# Subject pronouns and wh-words: often followed by a contraction, "let me", or an auxiliary.
SUBJECTS = {"I", "it", "It", "this", "This", "there", "There", "here", "Here", "let", "Let",
            "that", "That", "What", "what", "you", "You", "We", "we", "they", "They", "he", "He",
            "she", "She"}
CONTRACTIONS = {"'s", "’s", "'m", "’m", "'re", "’re", "'ve", "’ve", "'ll", "’ll", "'d", "’d"}
AUX_VERBS = {"is", "am", "are", "was", "will", "think", "seems", "hope", "can", "do", "have"}
# Sentence openers that are usually followed by a comma.
DISCOURSE_OPENERS = {"Yes", "So", "Thus", "However", "Now", "Hmm", "Oh", "Also", "Alternatively",
                     "Therefore", "Wait", "Indeed", "Well", "Still", "Actually", "Maybe", "Perhaps",
                     "Unfortunately", "Finally", "Anyway", "Overall", "Okay", "Ok"}
# Stock two-word phrases; the second word is the one that responds.
PHRASES = {("I", "think"), ("Thank", "you"), ("Of", "course"), ("How", "to"), ("how", "to"),
           ("Can", "you"), ("can", "you"), ("important", "to"), ("If", "you"), ("if", "you"),
           ("a", "little"), ("do", "you"), ("Do", "you"), ("need", "to"), ("have", "to"),
           ("going", "to"), ("one", "of")}
BLOCK_OPENERS = {"if", "for", "while", "switch"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    p, c = prev.strip(), cur.strip()
    # Library and domain names.
    if p in IMPORT_WORDS:
        if c == "org":
            return None, 8.0
        if c == "com":
            return None, 7.0
        if c.startswith(('"', "<")) or c == "{":
            return None, 4.5
        if c.islower():
            return None, 0.7
    if p in URL_SCHEMES and c == "://":
        return None, 5.5
    if prev == "://" and c == "www":
        return None, 5.0
    if p == "java" and cur.startswith("."):
        return None, 5.5
    if p == "github" and c == ".com":
        return None, 5.0
    if p in {"std", "console", "System"} and cur.startswith((".", "::")):
        return None, 2.3
    # Spoken style.
    if cur in CONTRACTIONS and p in SUBJECTS:
        return None, 2.0
    if p.lower() == "let" and c == "me":
        return None, 2.2
    if p in SUBJECTS and c in AUX_VERBS:
        return None, 0.8
    if p in DISCOURSE_OPENERS and c == ",":
        return None, 1.3
    if (p, c) in PHRASES:
        return None, 1.0
    # Code.
    if c == "return":
        return None, 1.2
    if p in BLOCK_OPENERS and c == "(":
        return None, 3.0
    if cur.strip() == "" and prev.strip() == "" and cur != "":
        return None, 0.4
    return None, 0.0

programs.sol:
"""A type-introduction heuristic, strongest on generic angle brackets.

Use naming and spacing to distinguish generic brackets from tags and
comparisons; explicitly reject closing tags, special tokens, '<=' and '<<'.
Nested type arguments have a weaker signal. Also recognize type-hint brackets,
annotation colons, return arrows, type bounds and JSDoc/declaration braces.
Other tokens predict zero.
The short text buffer and bracket depth reset at document boundaries.
"""
import re

READS = ()

# Lowercase C++ template containers, smart pointers and casts' result types.
CONTAINERS = {
    'vector', 'map', 'set', 'list', 'tuple', 'pair', 'deque', 'queue',
    'stack', 'array', 'optional', 'shared_ptr', 'unique_ptr', 'weak_ptr',
    'ref_ptr', 'priority_queue', 'greater', 'less', 'normal', 'singleton',
}
TYPE_HINTS = {
    'List', 'Dict', 'Tuple', 'Set', 'FrozenSet', 'Optional', 'Union',
    'Sequence', 'Iterable', 'Iterator', 'Callable', 'Mapping', 'Type',
    'Generic', 'Literal', 'Annotated', 'ClassVar',
    'list', 'dict', 'tuple', 'set', 'frozenset', 'type',
}
COMMON_TYPES = {
    'string', 'String', 'object', 'Object', 'int', 'bool', 'float',
    'double', 'number', 'boolean', 'str', 'Integer', 'Long', 'byte', 'char',
}
FUNCTION = r'\b(?:def|fn|func|function)\s+\w+\s*(?:<[^\n]*>)?\('


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, depth = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    s = token.strip()
    previous = ''
    if '<' in s or s.startswith('['):
        word = re.search(
            r'(?<![A-Za-z_0-9$])([A-Za-z_$][A-Za-z_0-9$]*)$',
            text.rstrip())
        previous = word[1] if word else ''
    container = previous in CONTAINERS
    type_name = len(previous) > 1 and previous[:1].isupper()
    function_name = (
        bool(re.search(r'[a-z][A-Z]', previous))
        or bool(re.fullmatch(r'[a-z]{3,}\d+', previous))
        or previous.endswith('_cast') or previous.startswith('make_')
        or bool(previous and re.search(
            r'\b(?:fn|function)\s+\w+$', text.rstrip()))
    )
    adjacent = bool(text) and not text[-1].isspace() and token.startswith('<')
    generic = (type_name or container or function_name
               or previous in {'impl', 'template'})
    generic = generic and (adjacent or container
                           or previous in {'template', 'impl'}
                           or s == '<' and '\n' in token)
    opening = s.startswith('<') and not s.startswith(
        ('<|', '</', '<!', '<<', '<=', '<-')
    )
    value = 0.0
    if s.startswith('::<'):
        value = -4.3
        depth += 1
    elif opening and generic:
        after = s[1:]
        if after.startswith('>'):
            magnitude = 2.0
        elif not after:
            magnitude = 10.0 if type_name else 7.6
            if '\n' in token:
                magnitude = 6.5
        elif after in COMMON_TYPES:
            magnitude = 9.5 if type_name else 6.8
        elif len(after) == 1 and after.isupper():
            magnitude = 7.2
        elif after.startswith(('typeof', '()', '{')):
            magnitude = 2.6
        else:
            magnitude = 6.0
        value = -magnitude * (0.8 if depth else 1.0)
        depth += 1
    elif s.startswith('[') and (previous in TYPE_HINTS | {'map'}
                                or re.search(r'\bfunc\s+\w+$', text)):
        value = -1.7
    elif s == ',' and depth:
        value = -1.2
    elif s in {'=', 'extends'} and depth:
        value = -1.4 if s == '=' else -1.8
    elif s == '=' and re.search(r'\btype\s+\w+$', text):
        value = -0.8
    elif s == '->' and re.search(FUNCTION, text):
        value = -1.4
    elif s in {':', '):', '():'} and '\n' not in token:
        line = text.rsplit('\n', 1)[-1]
        if depth or re.search(r'\bwhere\b', text):
            value = -1.4
        elif (re.search(FUNCTION + r'[^{}]*$', text)
              or re.search(
                  r'\b(?:let|const|var|class|interface|pub|private|'
                  r'public|protected)\s+\w+$', line)
              or s in {'):', '():'}):
            value = -1.0
    elif s == '{':
        if re.search(r'@(?:param|returns?|type)\s*$', text):
            value = -1.6
        elif re.search(r'\b(?:const|let|import)\s*$', text):
            value = -1.8
        elif re.search(r'\bexport\s*$', text):
            value = -0.9
    depth = max(0, depth - token.count('>'))
    if ';' in token or '\n\n' in token:
        depth = 0
    return (doc, (text + token)[-400:], depth), value

programs.haiku:
"""Generic-type opening bracket detector for layers.1.mlp.down_proj:2248.

This component is nearly silent on most text. It fires strongly negative on the "<" that
opens a type-argument list in typed code: `List<Contact>`, `Map<UUID, Item>`,
`GetComponent<Rigidbody>()`, `Callback<List<Check>>`, C++ `std::vector<int>`, and Rust's
`collect::<Vec<_>>`. The bracket is often merged with the first type name into one token
(`<String`, `<Key`, `<int`), and that merged token is what the rule sees.

The size depends on what the bracket follows and how it is written:

  * a bare "<" after a capitalised type or class name (List, Map, Callback, GetComponent,
    at least two letters): about -10;
  * a bare "<" after a lowercase name (vector, list, lift2): about -4, since C++ and Rust
    templates often use lowercase names;
  * a merged "<" plus a capitalised or primitive type name (`<String`, `<T`, `<int`,
    `<double`): about -7, whatever comes before it;
  * a Rust turbofish "::<": about -4;
  * everything else is 0. In particular comparisons such as `i<n` or `count<limit` after a
    single letter, and statistics such as `P<0.05`, stay quiet, as do HTML and XML tags.

The program is stateless: it looks at the current token and the one before it, and resets
at a document boundary. The magnitudes are typical values read off the data, not fitted per
type name.
"""

import re

READS: tuple[str, ...] = ()

BARE_AFTER_TYPE = -10.0
BARE_AFTER_LOWER = -4.0
MERGED_OPENER = -7.0
TURBOFISH = -4.0

PRIMITIVES = {
    "int", "double", "void", "number", "uint", "unsigned", "string", "bool", "char",
    "float", "long", "short", "byte", "object", "any", "boolean", "size_t",
}
IDENT_END = re.compile(r"([A-Za-z_][A-Za-z0-9_]*)$")


def _step_value(prev, cur):
    if cur.endswith("::<"):
        return TURBOFISH
    if not cur.startswith("<") or cur.startswith("</") or cur.startswith("<|"):
        return 0.0
    word = IDENT_END.search(prev)
    name = word.group(1) if word else ""
    if cur == "<":
        if len(name) > 1 and name[0].isupper():
            return BARE_AFTER_TYPE
        if len(name) > 1:
            return BARE_AFTER_LOWER
        return 0.0
    rest = cur[1:]
    if rest[:1].isupper() or rest in PRIMITIVES:
        if len(name) == 1 and rest not in PRIMITIVES:
            return 0.0
        return MERGED_OPENER
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    return None, _step_value(s[t - 1], s[t])

programs.sol:
"""A sparse syntax detector, strongest on star-prefixed documentation.

Comment margins and legal headers give positive responses; documentation
tag names have distinct signed responses. Starred Python arguments and XML
summary boundaries give negative ones. Smaller rules cover "most of",
underlined headings and closing double-dollar mathematics. Everything else is near zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', None)
    _, prev, line, math = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    previous = prev.strip()
    value = -0.002

    if word == '@' and previous == '*':
        # Root-level comments have a weaker response than indented ones.
        indent = len(line) - len(line.lstrip())
        value = 3.1 if indent <= 1 else 5.1
    elif previous == '@':
        if word == 'param':
            value = 1.65
        elif word == 'brief':
            value = -4.26
        elif word == 'return':
            value = -0.29
        elif word in {'throws', 'author', 'see', 'property', 'package'}:
            value = 1.36
    elif word == 'brief' and previous == '\\':
        value = -1.93
    elif word in {'Copyright', 'Created'} and previous == '*':
        value = 6.46
    elif word == 'Licensed' and previous == '*':
        value = 3.04
    elif word == '*' and re.fullmatch(r'[\s+\-\d]*', line):
        # A four-space indent followed by " *" is especially strong.
        if '\n' in token:
            value = 4.56 if prev == '    ' else 2.03
        else:
            value = 1.12 if prev == '    ' else 0.34
    elif word == '*/' and '\n' in token:
        value = 0.18
    elif word == 'args' and prev.rstrip().endswith('*'):
        value = -9.3
    elif word == 'kwargs' and prev.rstrip().endswith('**'):
        value = -6.83
    elif word == 'args' and previous == 'x':
        value = -1.97  # The shell utility xargs, split across tokens.
    elif word == 'summary' and previous in {'<', '</'}:
        value = -2.24 if previous == '</' else -0.45
    elif word == 'of' and previous.lower() == 'most':
        value = 0.85
    elif word == 'RUN' and previous == '===':
        value = 0.76
    elif re.fullmatch(r'\s*={3,}\s*', line):
        if token.isspace() and '\n\n' in token:
            # Distinguish heading underlines from long code separators.
            value = 5.0 if len(line.strip()) < 80 else 0.6
        elif word and set(word) == {'='} and len(word) >= 3:
            value = 0.86
    elif token == '$$':
        if math is None and not line.strip():
            value = 0.1  # Opening a displayed equation.
        elif re.search(r'\\end\{[^{}]+\}$', line):
            value = 3.76
        elif prev.rstrip().endswith(('.', ',')):
            value = 1.6
        else:
            value = 0.7 if math is False else -1.1

    # Remember whether the current double-dollar expression is displayed
    # (at a line boundary or spanning lines), rather than embedded in prose.
    if '$$' in token:
        if token == '$$':
            math = False if math is None and not line.strip() else None
        elif token.lstrip().startswith('$$'):
            math = bool(line.strip())
        else:
            math = None
    elif math is not None and '\n' in token:
        math = False
    line = (line + token).rsplit('\n', 1)[-1][-160:]
    return (doc, token, line, math), value

"""Approximate a strong, token-dependent document-opening write.

The opening dominates the activation's variance. It persists through exact
repetitions of the opening token. Elsewhere, predict zero except for control
markers, Greek-letter notation, decorative runs, and unusual spacing/symbols.
The constants are coarse training averages, not a token-ID lookup.
"""
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()
DECLARATIONS = {
    'import', 'package', 'using', 'use', 'class', 'interface',
    'namespace', 'public', 'private', 'protected', 'void', 'from',
}
GREEK_NAMES = set(('alpha beta gamma delta epsilon zeta eta theta iota '
                   'kappa lambda mu nu xi omicron pi rho sigma tau '
                   'upsilon phi chi psi omega').split())
MARKERS = {
    '<|im_start|>': 0.52,
    '<|im_end|>': -0.31,
    '<think>': -0.15,
    '</think>': 1.23,
    '<tool_call>': 0.84,
    '</tool_call>': -0.12,
    '<tool_response>': 0.33,
    '</tool_response>': 0.36,
}


def opening(s):
    t = s.strip()
    if s.startswith('<|'):
        return -5.0
    if not t:
        if s == '\r':
            return 2.6
        if '\n' in s:
            return -3.5 if '\r' in s else -1.5
        if '\t' in s:
            return -3.8 if len(s) == 1 else -5.0
        return -5.0 if len(s) == 1 else -7.8
    if t.isdecimal() and t.isascii():
        return -3.6 - 0.35 * int(t[0])
    if not s[0].isspace() and t in DECLARATIONS:
        return -13.3
    if t.startswith('#include'):
        return -5.1
    if t.startswith(('#', '/*', '//')):
        return -9.0
    if t.isalpha() and t.isascii():
        common = zipf_frequency(t, 'en') > 4
        if t[0].isupper():
            return -7.8 if common or len(t) < 4 else -6.6
        if s[0].isspace():
            return (-7.6 if common else -6.9) if len(t) > 3 else -6.5
        return -5.7 if common and len(t) > 3 else -5.2
    return -4.6 if any(c.isalpha() for c in t) else -3.6


def later(s, previous, raw, tail, word):
    t = s.strip()
    if s in MARKERS:
        return MARKERS[s]
    if t.lower() in GREEK_NAMES or word.lower() in GREEK_NAMES:
        return 0.6
    if len(t) == 1 and 'GREEK' in unicodedata.name(t, ''):
        return 0.1
    if '\x00' in s:
        return 1.15
    if '\xa0' in s:
        if '\n' in s:
            return -0.25
        if s.count('\xa0') == 1:
            return -0.3 if '\xa0' in previous else 0.45
        return 0.2 if len(s) < 7 else 0.9
    if len(t) >= 4 and len(set(t)) == 1:
        if t[0] in '-_=':
            height = 0.9 if t[0] == '=' else 1.6
            return height * min(1, len(t) / 64) ** 3
        if t[0] in '^!\\─':
            return 0.9
    if t == '··':
        return 0.7
    # UTF-8 tokens can stop partway through an emoji or a dingbat.
    raw = raw.lstrip(b' ')
    if '\ufffd' in s:
        if raw.startswith(b'\xf0\x9f'):
            return 1.6
        if raw.startswith(b'\xe2\x9c'):
            return 0.6
    ch = tail.decode('utf-8', 'ignore')[-1:]
    if ch in '✓✔✗✘' and ch:
        return 0.6
    if ch == '\ufe0f':  # emoji presentation selector
        return 1.5
    if regex.fullmatch(r'[\p{Extended_Pictographic}\p{Regional_Indicator}]', ch):
        if ch not in '©®™':
            return 1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, opening_run, word, tail = '', True, '', b''
    else:
        _, previous, opening_run, word, tail = carry
        opening_run = opening_run and raw == prefix.token_bytes[-2]
    tail = (tail + raw)[-12:]
    for c in s:
        word = (word + c)[-20:] if c.isascii() and c.isalpha() else ''
    value = opening(s) if opening_run else later(s, previous, raw, tail, word)
    return (doc, s, opening_run, word, tail), value

programs.haiku:
"""Document-start detector for layers.1.mlp.down_proj:2252, plus chat-format markers.

What it does: this component is nearly silent inside a document, but at the very first
token of each document (the first token of a row, or the first token after a document
boundary `<|endoftext|>`, where the model has no earlier text to look at) it writes a strong
negative value. The size depends on what the token looks like:
  - ordinary words (English words, code keywords such as `import`, `public`, `const`):
    about -7, longer words a little more negative;
  - ALL-CAPS words (`DROP`, `CREATE`): about -8;
  - camelCase identifiers (`setBackgroundColor`, `userName`): about -3.5;
  - digits, punctuation, symbols, emoji, newlines, and other scripts: about -4, or about
    -3 for punctuation and symbols (newlines, emoji and punctuation are the least negative).
Inside a document it is nearly zero, except on the chat-format markers of the Qwen chat
template, which give small positive values (`</think>`, `<tool_call>` and `<|im_start|>`
the most) and `<|im_end|>` a small negative one.
Every other position predicts 0.

The program reads only the newest token and whether the document id changed, so it keeps no
state beyond what `prefix` already holds.
"""

READS = ()

CHAT_MARKERS = {
    "</think>": 1.25,
    "<tool_call>": 0.8,
    "<|im_start|>": 0.5,
    "<tool_response>": 0.35,
    "</tool_response>": 0.35,
    "<|im_end|>": -0.3,
}


def _is_document_start(prefix) -> bool:
    t = prefix.position
    return t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]


def _document_start_value(text: str) -> float:
    body = text.strip()
    if "�" in text or body == "":
        return -4.0
    if body.isalpha() and body.isascii():
        if body.isupper() and len(body) > 1:
            return -8.0
        if any(c.isupper() for c in body[1:]):
            return -3.5  # camelCase identifier
        return -7.5 if len(body) >= 5 else -6.7
    if body.isalpha():  # letters in other scripts
        return -4.5
    return -4.0 if body.isalnum() else -3.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[prefix.position]
    if _is_document_start(prefix):
        return None, _document_start_value(text)
    return None, CHAT_MARKERS.get(text, 0.0)

programs.sol:
"""Approximate header and source-code boundary responses using text rules.

The largest response is the colon in a document-initial 'Title:' header.
Other positive cases are visibility declarations, call/statement endings,
and Markdown links.  Text around '(' distinguishes calls from prose or math.
Noninitial imports, closing blocks, and backticks have small negative responses.
Only a short text suffix is carried, reset at each document boundary.
"""
import re

READS = ()
VISIBILITY = {
    'public': 1.5,
    'private': 0.7,
    'protected': 1.65,
    'internal': 1.7,
    'pub': 0.65,
    'static': 0.8,
}


def closing_parenthesis(before):
    opening = before.rfind('(')
    left, inside = before[:opening], before[opening + 1:]
    line = before.rsplit('\n', 1)[-1]
    call = opening >= 0 and bool(re.search(r'[\w\])]$', left))
    code = bool(re.search(
        r'[=;{}]|\n[ \t]{2}|\b(?:return|def|class|import)\s|'
        r'\b(?:if|for|while|catch)\s*\(', before[-180:]))
    definition = bool(re.search(
        r'\b(?:func|function|def|public|private|protected|internal)\b', line))
    control = bool(re.search(r'\b(?:if|for|while|catch|switch)\s*$', left))
    math = bool(re.search(r'\\(?:frac|left|right|sum|mathrm|sin|cos)', before))
    math |= '$' in before and before.count('$') % 2 == 1 and not code
    cast = opening >= 0 and not call and bool(re.fullmatch(r'[A-Z]\w*', inside))
    if math or cast:
        return -0.02
    return 0.05 + 0.17 * call + 0.14 * code + 0.32 * definition + 0.49 * control


def activation(text, before):
    if not before and text == 'Title':
        return 2.6
    if before == 'Title' and text == ':':
        return 10.2
    s = text.strip()
    before = before.replace('\\n', '\n').replace('\\t', '\t')
    line = before.rsplit('\n', 1)[-1]
    # Ignore source-listing line numbers and diff signs before indentation.
    line = re.sub(r'^\s*\d+[:\t]', '', line).lstrip('+-')
    indent = len(line.expandtabs(4)) if not line.strip() else -1
    if s == 'static':
        previous = re.search(r'\b(\w+)\s*$', before)
        previous = previous[1] if previous else ''
        if previous in {'public', 'private', 'protected', 'internal', 'import'}:
            return {'public': 1.75, 'internal': 2.2, 'import': -0.35}.get(
                previous, 1.25)
    if s in VISIBILITY and (indent >= 0 or text.startswith('\t')):
        width = indent + len(text) - len(text.lstrip())
        value = VISIBILITY[s]
        if s == 'public':
            value = 1.05 if width < 2 else 1.85 if width >= 8 else 1.5
        if s == 'private' and width >= 8:
            value += 0.5
        if s in {'public', 'protected'} and re.search(r'@Override\s*$', before):
            value += 0.55
        return value
    if s in {'Override', '@Override'} and ('@' in text or before.endswith('@')):
        return 0.96
    if s == 'func' and not line.strip():
        return 0.82
    if s in {'import', 'package'} and not line.strip():
        return 1.75 if not before and s == 'import' else -0.2
    if s == '=>':
        return 0.7 if text.startswith(' ') else 0.05
    if s.startswith('/*'):
        return 1.8 if not before else 0.35
    if text.isspace():
        return -0.015
    if not s or any(c.isalnum() for c in s):
        return -0.004
    if '](' in s:
        return 1.16
    if s == '#' and before.endswith(']('):
        return 1.5
    n = text.count('\n')
    if ')' in s:
        if s[-1] in '.=^/$+-*>' or ')(' in s:
            return 0.12 if '().' in s else -0.02
        if ';' in s:
            return (0.5 + 0.2 * ('()' in s or '))' in s)
                    + 0.3 * s.endswith('\\') - 0.15 * (n > 1))
        if s.endswith(','):
            return 0.42 if n == 1 else 0.0
        if s.endswith(':'):
            return 0.37 if n == 1 else 0.06
        if '()' in s:
            return 0.5 + 0.23 * (s.count(')') > 1) - 0.15 * bool(n)
        if s.count(')') > 1:
            return 0.48 - 0.12 * bool(n)
        if s.startswith(("'", '"', ']')):
            return 0.42
        value = closing_parenthesis(before)
        return value * (0.65 if n == 1 else 0.25 if n > 1 else 1.0)
    if ';' in s:
        return 0.55 if s.endswith('\\') else 0.27 if n == 1 else 0.12 if n else 0.035
    if s.endswith(','):
        return (0.22 if n == 1 else 0.075) if n else 0.22 * s.endswith('\",')
    if '}' in s:
        return -0.2 if n > 1 else -0.12
    if s == ']':
        return 0.12 if re.search(r'[=;{}]|\n[ \t]{2}', before) else -0.04
    if s in {'":', "':"}:
        return -0.12
    if s == '`':
        return -0.08
    return -0.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, (before + text)[-320:]), activation(text, before)

programs.haiku:
"""Component layers.1.mlp.down_proj:2256: a source-code punctuation detector.

What it responds to, read off its activations on training text:
  * Strongest: the access modifier (or @Override) that opens a new class member on
    its own indented line: the `public` in `    }\n\n    public void load()`.
    The same word in English prose gives nothing.
  * Closing brackets in code. For each `)`, the program looks at the text before
    the matching `(`:
      - the parameter list of a function definition (`function (x) {`, `=> {`,
        `def f(x)`): strong, about 0.6;
      - the parameter list of a method or variable declaration (`void f(`,
        `String s(`): about 0.45;
      - an ordinary call or grouping (`foo(x)`, `f(a)(b)`): weaker, about 0.2,
        and about 0.55 when the token also ends the statement (`);`);
      - anything else (a cast, a parenthesised phrase): about 0.1.
  * Everything else (ordinary words, digits, spaces, newlines, prose) is near zero.

It reads left to right and keeps only: the text of the current line, the last
100 characters, and a stack of open brackets. Rows start mid-document, so a `)`
with no opener in view counts as a call. This is a readable rule, not a model
of the network. It explains about 13% of the component's variance.
"""

import re

READS = ()

MODIFIERS = {"public", "private", "protected", "static", "@Override"}
MEMBER_START = 1.3

FUNCTION_HEAD = re.compile(r"(function\s*\w*|=>|\bdef\s+\w+)\s*$")
DECLARATION_HEAD = re.compile(
    r"\b(public|private|protected|static|void|int|String|bool|float|async)\b[^=;{}()]*\s\w+\s*$"
)
CALL_HEAD = re.compile(r"[\w\]\)]\s*$")

VALUE = {"function": 0.6, "declaration": 0.45, "call": 0.2, "other": 0.1}
CALL_STATEMENT = 0.55   # a call closed and the token ends the statement, as in ");"
STATEMENT_END = 0.07    # a semicolon with no closing bracket


def classify_opener(before):
    """What a '(' opens, from the text before it."""
    tail = before[-60:]
    if FUNCTION_HEAD.search(tail):
        return "function"
    if DECLARATION_HEAD.search(tail):
        return "declaration"
    if CALL_HEAD.search(tail):
        return "call"
    return "other"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "line": "", "text": "", "opens": []}
    line_before = carry["line"]
    text = carry["text"]
    opens = list(carry["opens"])

    closer = None          # category of the last ')' in this token
    for ch in token:
        if ch == "(":
            opens.append(classify_opener(text))
        elif ch == ")":
            closer = opens.pop() if opens else "call"
        text = (text + ch)[-100:]
    opens = opens[-64:]

    if line_before.strip() == "" and token.strip() in MODIFIERS:
        value = MEMBER_START
    elif closer is not None:
        value = VALUE[closer]
        if closer == "call" and token.rstrip().endswith(";"):
            value = CALL_STATEMENT
    elif token.rstrip().endswith(";"):
        value = STATEMENT_END
    else:
        value = 0.0

    line = token.split("\n")[-1] if "\n" in token else line_before + token
    return {"doc": doc, "line": line, "text": text, "opens": opens}, float(value)

programs.sol:
"""Document-opening source-code syntax, not comments throughout a file.

Block-comment and triple-quote openers produce a positive pulse at the
first token of a document. Imports and a blank // line produce a negative
pulse. Newlines, indentation and documentation-comment stars distinguish
several common spellings. Most other tokens get a near-zero background.
The many smaller, word-specific fluctuations are not modeled.
"""
READS = ()

# Keywords/directives that introduce a source file.
FILE_STARTS = {
    'import': -1.28,
    'from': -0.67,
    'package': 0.54,
    '#include': 0.24,
    '#pragma': -0.40,
}


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    token = prefix.token_strings[-1]
    value = -0.0017
    if not first:
        return None, value

    bare = token.rstrip('\r\n')
    newline = token.endswith('\n')
    if token in FILE_STARTS:
        value = FILE_STARTS[token]
    elif bare.startswith('/*'):
        if bare == '/**':
            value = 1.39 if '\r' in token else 1.80 + 0.14 * newline
        elif bare == '/*':
            value = 0.46 + 0.48 * newline
        elif bare == '/*!':
            value = 1.66
        else:  # decorative star or dash banners
            value = 1.30
    elif bare.lstrip() in ('"""', "'''"):
        if bare != bare.lstrip():
            value = 0.65
        else:
            value = 1.35 + 0.50 * newline
    elif bare == '""' and newline:
        value = 1.36
    elif bare == '//' and newline:
        value = -1.87
    elif bare.startswith('#!'):
        value = 1.39 if bare == '#!' else 0.75
    elif token == ' *':  # a row may begin partway through a block comment
        value = 1.28
    return None, value

"""Text-boundary pulses, rather than a general semantic feature.

The largest positive rules concern hexadecimal byte escapes, percent
formats, and unbraced fraction numerators. Negative rules concern long
accented Latin vowels followed by consonants, especially caron letters.
A few small syntax rules cover diff hunks, templates, encoding declarations,
and Python receivers. These are approximate training-derived amplitudes;
unmatched tokens get zero, leaving smaller lexical variation unexplained.
Only a short suffix and the previous token are remembered within a document.
"""
import re
import unicodedata as ud

READS = ()

# C/Go format codes: quoted strings, types, errors, integers, values, strings.
FORMAT_CODES = {
    'q': 3.7, 'T': 4.7, 'w': 1.7,
    'd': 0.7, 'v': 0.8, 's': 0.4,
    'lu': -0.6, 'ld': -0.6, 'lf': -0.6,
    '+': 6.5, '*': 5.3, '*[': 5.3,
}


def activation(previous, recent, token):
    if not token:
        return 0.0
    word = token.strip()

    # First hex nibble, or the letter bytes in escaped UTF8 ligatures.
    if recent.endswith('\\x'):
        if token == '0':
            return 9.6
        if token in ('8', '9'):
            return 4.1
        if token == 'ef':
            return -3.0
        if token == 'ac':
            return -7.4
    if recent.endswith('\\xc') and token == '2':
        return 1.25

    # Adjacent percent syntax, allowing one space but not a new line.
    if re.search(r'% ?\Z', recent):
        if word.isascii() and word.isdigit():
            if word == '0':
                return 7.5
            return 6.0 if word == '2' else 3.3
        if token == word:
            if word == 'load':  # IPython's %load magic.
                return -12.0
            if word in FORMAT_CODES:
                return FORMAT_CODES[word]
    if re.search(r'(?:\\[dt]?frac|&frac)\Z', recent):
        if len(word) == 1 and word.isascii():
            if word.isdigit():
                return 10.3
            if word.isalpha():
                return 7.2
    if recent.endswith('@@') and token == ' -':
        return 1.2
    if recent.endswith('{%') and token == ' end':
        return 2.0
    if token == ' charset' and previous.endswith(('"', "'")):
        return -3.0
    if word in ('UTF', '=UTF') and 'charset' in recent.lower():
        return -8.0 if word == 'UTF' else -4.4

    latin_letter = ud.name(token[0], '').startswith('LATIN ')
    if previous and token[0].isalpha() and latin_letter:
        vowel = ud.normalize('NFD', previous[-1].lower())
        long_vowel = (vowel[:1] in 'aeiouy' and len(vowel) > 1
                      and any(m in vowel for m in ('\u0301', '\u0302', '\u030a')))
        if long_vowel or previous.endswith('ou'):
            first = ud.normalize('NFD', token[0])
            if '\u030c' in first:
                # The Czech/Slovak 'použ-' use-stem is much weaker.
                if previous.endswith('pou') and token == 'ž':
                    return -0.5
                if len(token) > 1:
                    following = ud.normalize('NFD', token[1])[:1]
                    if following in 'aeiouy':
                        return -1.7
                if vowel.startswith('u') and '\u0301' in vowel:
                    return -8.9
                return -6.3
            if previous[-1] in 'áíý' and len(token) <= 2:
                if token[0] in 'ptkd':
                    return -1.6
                if previous[-1] == 'á' and token[0] == 'n':
                    return -1.35
    if token == 'á':
        return -0.33
    if token == ' ú':
        return -1.0
    if recent.endswith('__(') and token == 'self':
        return -0.74
    if recent.endswith('&#') and word.isascii() and word.isdigit():
        return 0.53
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    value = activation(previous, recent, token)
    return (doc, token, (recent + token)[-40:]), value

"""A mixture of typographic, mathematical and English-aspect cues.

Positive responses cover long dashes, several quotation marks, tildes,
repeated middle dots, nonbreaking spaces and mojibake markers. Greek letter
names after a TeX backslash, and isolated Greek symbols, also contribute.
'Just', 'already' and 'always' are negative, especially after perfect-tense
auxiliaries, contractions or subject pronouns. Two smaller rules cover
'have recently' and 'not even'. These are separate response families, not
one proposed semantic category.

A 64-character suffix supplies grammatical context. Incomplete UTF-8 bytes
are retained so a split character can be recognized when it finishes.
Document boundaries reset both. Unmatched tokens receive -0.003, or 0.12
at document start. Small background variation and unrelated rare lexical
exceptions are deliberately not modeled.
"""
import re
import unicodedata

READS = ()

GREEK = {
    'alpha': .20, 'beta': .34, 'gamma': .40, 'delta': .22,
    'epsilon': .33, 'zeta': .67, 'eta': .40, 'theta': .11,
    'kappa': .65, 'lambda': .19, 'mu': .22, 'nu': .43,
    'xi': .50, 'pi': .18,
    'rho': .53, 'sigma': .43, 'tau': .52, 'phi': .33, 'chi': .96,
    'psi': .66, 'omega': .31, 'varphi': .30, 'vartheta': .33,
}
ASPECT = {'just': -.20, 'already': -.15, 'always': -.03}
PERFECT = re.compile(r"(?:\b(?:have|has|had)|['’]ve)$", re.I)
COPULA = re.compile(
    r"(?:\b(?:is|was|were|are|am)|['’](?:s|m|re))$", re.I
)
TEX = re.compile(r'\\([A-Za-z]*)$')


def predict(s, tail, first, raw):
    w = s.strip()
    value = .12 if first else -.003
    if '—' in s:
        value = .76 if s.startswith(' ') else .40
    elif '–' in s:
        value = .25 if s.startswith(' ') else .13
    elif '«' in s:
        value = .62
    elif '»' in s:
        value = .35 if s.startswith(' ') else .25
    elif '「' in s or '『' in s:
        value = .40 if '「' in s else .31
    elif '」' in s or '』' in s:
        value = .20 if '」' in s else .16
    elif w and all(c in '~～〜' for c in w):
        value = .60 if '~' in w else .39
    elif '·' in s:
        value = .75 if '··' in s else .10
    elif '\xa0' in s:
        value = .18
    elif '„' in s:
        value = .32
    elif w in ('â', 'Â'):
        value = .55
    elif w == 'χ':
        value = .77
    elif w in ('ψ', 'Ψ'):
        value = .48
    elif w == '°':
        value = .20
    elif raw.endswith(b'\xc2'):
        value = .88 if len(raw) > 1 else .68
    elif raw == b' \xcf':
        value = .31
    if w in ASPECT:
        value = ASPECT[w]
        if PERFECT.search(tail):
            value = {'just': -1.2, 'already': -.95, 'always': -.88}[w]
            if re.search(r"['’]ve$", tail, re.I):
                value = {'just': -1.2, 'already': -1.4, 'always': -1.1}[w]
        elif re.search(r"['’](?:s|m|re)$", tail, re.I):
            value = {'just': -.95, 'already': -.5, 'always': -.25}[w]
        elif re.search(r'\b(?:I|we)$', tail, re.I):
            value = {'just': -.70, 'already': -.75, 'always': -.15}[w]
        elif re.search(r'\b(?:you|he|she|it|they)$', tail, re.I):
            value = {'just': -.50, 'already': -.30, 'always': -.12}[w]
        elif re.search(r'\b(?:was|were)$', tail, re.I):
            value = {'just': -.65, 'already': -.52, 'always': -.35}[w]
        elif COPULA.search(tail):
            value = {'just': -.37, 'already': -.22, 'always': -.15}[w]
    elif w == 'recently' and PERFECT.search(tail):
        value = -.7
    elif w == 'even' and re.search(r'\bnot$', tail, re.I):
        value = -.43
    command = TEX.search(tail)
    if command:
        name = command[1] + w
        if name in GREEK:
            value = GREEK[name]
    elif s in ('psi', 'phi', 'tau', 'rho', 'sigma'):
        value = .22
    # Isolated Greek symbols in mathematical prose (not ordinary Greek words).
    if len(w) == 1 and 'GREEK' in unicodedata.name(w, ''):
        name = unicodedata.name(w, '').split()[-1].lower()
        greek_context = sum(
            'GREEK' in unicodedata.name(c, '') for c in tail[-24:]
        )
        if (name in GREEK and greek_context < 3
                and name not in ('chi', 'psi')):
            value = GREEK[name]
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    raw = prefix.token_bytes[-1]
    pending = b'' if first else carry[2]
    joined = pending + raw
    s = joined.decode('utf-8', 'ignore')
    value = predict(s, tail, first, raw)
    # Retain an unfinished UTF-8 character, so split symbols are recognized.
    pending = b''
    for i in range(len(joined) - 1, max(-1, len(joined) - 5), -1):
        b = joined[i]
        if b < 128:
            break
        if b >= 192:
            need = 2 if b < 224 else 3 if b < 240 else 4
            if len(joined) - i < need:
                pending = joined[i:]
            break
    return (doc, (tail + s)[-64:], pending), float(value)

programs.haiku:
"""Dashes, guillemets, tildes and similar typographic marks light up; the adverbs
"just", "already", "always" are pushed negative when they follow a subject or auxiliary
("I just", "It's just", "have already", "has always"). Everything else is near zero.

Values are rough group means of the component's activation on training text."""

READS = ()

DASHES = {"—", " —", "——"}              # em dash, with or without a space before it
EN_DASHES = {"–", " –"}                 # en dash
MIDDLE_DOTS = {"··", "·", " ·"}         # interpunct
TILDES = {"~", " ~", "~~", "〜", "～"}
ANGLE_QUOTES_OPEN = {"«", " «", "「", "『", "„", " „", "、「"}
ANGLE_QUOTES_CLOSE = {"»", " »"}
NBSP = {"\xa0"}
ADVERBS = {" just", " already", " always", " even"}
# Words right before the adverb that make it a predicate adverb: subject pronouns,
# auxiliaries and contractions.
SUBJECT_OR_AUX = {
    "I", " I", "it", " it", "we", " we", "you", " you", "they", " they", "he", " he", "she", " she",
    " is", " are", " was", " were", " be", " have", " has", " had", "have", "has", "had",
    "’s", "'s", "’ve", "'ve", "’re", "'re", "’m", "'m", "’d", "'d", "’ll", "'ll",
}
REPLACEMENT = "�"                  # half of a multi-byte character


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.13
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in DASHES or tok in MIDDLE_DOTS:
        return None, 0.75
    if tok in TILDES:
        return None, 0.55
    if tok in ANGLE_QUOTES_OPEN:
        return None, 0.46
    if tok in EN_DASHES:
        return None, 0.22
    if tok in ANGLE_QUOTES_CLOSE:
        return None, 0.26
    if tok in NBSP:
        return None, 0.16
    if tok == REPLACEMENT:
        return None, 0.09
    if tok in ADVERBS:
        return None, -0.5 if prev in SUBJECT_OR_AUX else -0.12
    return None, 0.0

"""Demonstratives (this/that/these/those and foreign equivalents) go negative when
they sit after a preposition, i.e. as the object of a phrase ("in this", "for that"),
and weakly otherwise. 'that' that opens a clause ("said that") stays near zero.
Quantifiers that pick out a whole (every, whole) go mildly negative; concrete
physical nouns after "the" (sun, air, door, stage) go mildly positive."""
READS = ()
FOREIGN = {
    "ce", "cet", "cette", "ces", "cela", "ceci", "este", "esta", "estos", "estas",
    "esse", "essa", "questo", "questa", "questi", "queste", "dieses", "diese", "dieser",
    "这", "这个", "这种", "这些", "那个", "那种", "那些", "這", "這個", "這種", "この", "その", "あの",
    "этого", "этот", "эта", "này", "cái",
}
PHYSICAL = {"sun", "air", "sky", "water", "earth", "dust", "sand", "door", "wheel", "oven",
    "camera", "phone", "stage", "needle", "dough", "curtain", "window", "kitchen"}
PREPOSITIONS = {"in", "on", "of", "at", "to", "for", "with", "from", "about", "into",
    "during", "through", "by", "like", "after", "over", "under", "onto", "throughout"}
BOUNDARY = {"", ".", "\n", "\n\n", '"', ",", "and", "but", "so", "is", "=", "return"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    after_prep = prev in PREPOSITIONS
    if word in FOREIGN:
        return None, -1.5 if after_prep else -0.7
    if word == "that":
        return None, -1.5 if after_prep else 0.0
    if word in {"this", "these", "those"}:
        if after_prep:
            return None, -1.3
        if prev in BOUNDARY:
            return None, -0.3
        return None, -0.5
    if word in {"every", "whole"}:
        return None, -0.35
    if word in PHYSICAL and prev == "the":
        return None, 0.4
    return None, 0.0

programs.sol:
"""A coarse boundary-and-lexical approximation, not an exact activation model.

Document beginnings have a negative bias, strongest for code declarations and
headings, weaker for capitalized words and separators. Away from the boundary,
filename suffixes and a few grammatical/semantic classes give small offsets.
Two initial header/namespace patterns and month names followed by 30 or 31
get explicit context rules. State resets at each document and retains only a
short text tail.
"""
import calendar
import re

READS = ()

DECLARATIONS = frozenset(
    'class package import namespace using include pragma def function public '
    'private protected static struct enum interface const var let typedef '
    'int char void float double bool boolean use'.split()
)
SOURCE = frozenset(
    'c cc cpp cxx h hpp java py rb rs go js ts tsx jsx vue sh bash php pl cs '
    'swift kt scala lua r m f for f90 css scss html htm sql'.split()
)
CONFIG = frozenset('mod sum json xml yaml yml toml ini cfg conf config lock list'.split())
TEXT = frozenset('txt md rst tex doc docx odt pdf rtf'.split())
ARCHIVE = frozenset('zip tar gz bz bz2 xz rar 7z jar war tgz'.split())
OBLIGATION = frozenset(
    'should must ought necessary required need needs requirement obligation '
    'mandatory compulsory essential'.split()
)
POSSIBILITY = frozenset(
    'can could may might possible possibly possibility potential potentially '
    'perhaps maybe probable probably likely unlikely presumably'.split()
)
SIMILARITY = frozenset(
    'same similar similarity identical identity equivalent equivalence alike equal equality'.split()
)
CONTRAST = frozenset('but however although though yet nevertheless nonetheless whereas'.split())
MONTH_END = re.compile(
    r'\b(?:' + '|'.join(calendar.month_name[1:]) + r')\s+3[01]$', re.I
)


def activation(token, initial):
    s = token.strip()
    word = s.lower()
    if initial:
        value = -0.14 - 0.05 * token.startswith(' ')
        if word.lstrip('#') in DECLARATIONS:
            value -= 0.36
        if s.startswith('#'):
            value -= 0.15
        if s.isascii() and s.isalpha():
            if s[:1].isupper() and s[1:].islower():
                value += 0.11
            if 2 <= len(s) <= 3:
                value += 0.04
        if '\n' in token:
            value += 0.10
        if not s:
            value += 0.08
        elif all(c in ',.;:' for c in s):
            value += 0.14
        elif all(c in '[]{}()' for c in s):
            value += 0.09
        return value

    if s.startswith('.') and s[1:].isalpha():
        extension = s[1:].lower()
        for group, value in ((CONFIG, -0.12), (TEXT, -0.10),
                             (ARCHIVE, -0.09), (SOURCE, -0.04)):
            if extension in group:
                return value
    if word in OBLIGATION:
        return -0.025
    if word in POSSIBILITY:
        return -0.016
    if word in SIMILARITY:
        return 0.029
    if word in CONTRAST:
        return 0.013
    if word in {'and', 'or', 'nor'}:
        return -0.006
    if word in {'if', 'unless', 'whether'}:
        return -0.011
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first, initial, tail = token_id, True, ''
    else:
        _, first, initial, tail = carry
        initial = initial and token_id == first
    value = activation(token, initial)
    if tail == 'Title' and token == ':':
        value = -1.35
    elif tail == 'package' and token == ' com':
        value = 0.515
    text = (tail + token)[-64:]
    if token in ('0', '1') and MONTH_END.search(text):
        value = 0.38
    return (doc, first, initial, text), value

programs.haiku:
"""Relative-clause pronouns after a preposition or a place/time noun.
Strongly negative on relative 'where', 'when', 'which' (and foreign equivalents) when they
open a restrictive clause after 'in', 'at', 'a country', 'the time', etc.; near zero otherwise."""
READS = ()

PREPS = {" in", " during", " at", " for", " on", " from", " to", " within", " into", " upon",
         " under", " through", " by", " with", " of", " after", " among", " around", " over", " above"}
PLACE_TIME = {" time", " times", " day", " days", " case", " cases", " country", " area", " world",
              " place", " places", " point", " points", " situation", " situations", " year", " years",
              " moment", " stage", " circumstances", " occasion", " week", " night", " nights", " way",
              " environment", " context", " condition", " conditions", " period", " season", " era", " age"}
NOT_NOUN = {" is", " to", " and", " or", ":", " was", " be", " are", " know"}
FOREIGN = {" où", " donde", " где", " когда", " gdzie", " cui", " hvor", " wherein", " whereby"}
def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in FOREIGN:
        return carry, -3.0
    if tok == " where":
        if prev in PLACE_TIME:
            return carry, -5.5
        if prev in NOT_NOUN:
            return carry, -0.5
        return carry, -3.0
    if tok == " when":
        if prev in PLACE_TIME:
            return carry, -8.0
        if prev in PREPS:
            return carry, -3.0
        if prev == ",":
            return carry, -1.5
        return carry, 0.0
    if tok in (" which", " whom"):
        if prev in PREPS:
            return carry, -3.0
        if prev == ",":
            return carry, 0.0
        return carry, -0.5
    return carry, 0.0

programs.sol:
"""Sparse scientific-text formatting cues.

The main negative pulses mark numeric-reference chains, parenthetical
figure/table labels, and single line breaks closing section headings.
Blank-line count and academic vocabulary are heuristics for distinguishing
headings from code and ordinary lists. Later reference junctions are stronger than the first.
A small amount of document state also recognizes paragraph-ending breaks
in this style. Three minor rules cover supplementary-file references,
the firstname.lastname email placeholder, and repeated middle-dot tokens.
Amplitudes are empirical averages, not a reconstruction of the MLP.
"""
import re

READS = ()
SECTIONS = {
    'abstract', 'introduction', 'background', 'methods', 'method',
    'methodology', 'materials and methods', 'results',
    'results and discussion', 'discussion', 'conclusion', 'conclusions',
    'acknowledgments', 'acknowledgements', 'acknowledgment',
    'references', 'conflict of interest', 'funding',
}
ACADEMIC = re.compile(
    r'\b(study|results|model|data|analysis|method|equation|patients|'
    r'significant|experiments|algorithm)\b', re.I
)
CITATION = re.compile(r'(?:^|[ ,])((?:\[\d+\])*\[\d+)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, False)
    # Bounded text suffix, current line, breaks before that line, style flag.
    _, tail, line, gap, scientific = carry
    s = prefix.token_strings[-1]
    value = 0.0
    citation = CITATION.search(tail)
    count = citation[1].count('[') if citation else 0

    if s == '][':
        value = (-4.0 if count == 1 else -7.0) if count else 0.0
    elif s.startswith(']') and count:
        if s == ']':
            value = -3.0 if count > 1 else 0.0
        elif s == '].':
            value = -0.5
        elif s == '].\n':
            value = -2.6
        elif s.startswith('].\n\n'):
            value = -0.9
    elif s.strip() in {'Figure', 'Table', 'Fig'}:
        label = s.strip()
        if s.startswith(' ') and tail.rstrip().endswith('('):
            value = -6.6 if label == 'Figure' else -4.0
        else:
            value = -0.8 if label == 'Figure' else -0.2
        scientific = True
    elif s == ' where':
        if tail.rstrip().endswith(':'):
            value = -3.0
        elif (re.search(r'\b(as|form|with)$', tail)
              or re.search(r'\b(matrix|potential|equation|formula) is$', tail)):
            value = -2.5
    elif s == ' file' and tail.endswith('Additional'):
        value = 4.9
    elif s == '.lastname' and tail.endswith('firstname'):
        value = -4.8
    elif len(s) >= 2 and set(s) == {'·'}:
        value = 1.2

    if '\n' in s:
        parts = s.split('\n')
        full = line + parts[0]
        words = re.findall('[A-Za-z]+', full)
        heading = (
            0 < len(full) <= 150 and 0 < len(words) <= 20
            and full[0].isupper()
            and re.fullmatch(r"[A-Za-z0-9 '’():,./+&–—-]+", full)
            and not full.rstrip().endswith(('.', ':', ';', ','))
        )
        if s.count('\n') == 1:
            if heading and gap >= 2:
                main = full.strip().lower() in SECTIONS
                academic = scientific or bool(ACADEMIC.search(tail))
                if main:
                    value = -9.0 if gap >= 3 else (-4.7 if academic else -2.0)
                else:
                    value = -1.8 if academic else -0.3
                if main and full.strip().lower() not in {
                    'background', 'references'
                }:
                    scientific = True
            elif value == 0 and s.endswith('.\n') and len(words) > 8:
                value = -1.0 if scientific else 0.0
        for part in parts[:-1]:
            gap = min(4, gap + 1) if not (line + part).strip() else 1
            line = ''
        line = parts[-1]
    else:
        line = (line + s)[-256:]
    if count and s.startswith(']'):
        scientific = True
    tail = (tail + s)[-200:]
    return (doc, tail, line, gap, scientific), float(value)

"""Sparse lexical pulses, strongest for Chinese palm/drum/approval words.

This is a mixed lexical feature, not a single semantic category. Tiger,
cauldron, dance and divination characters are additional negative triggers.
Compounds tend to be weaker. It also handles thumb words, a few cross-script
letters, Chinese characters completed across token boundaries, and the
positive offset at document beginnings. A leading 12, numbered bold headings
and decorative runs of middle dots receive positive pulses. Other text gets
a near-zero baseline.
"""
READS = ()

# (Character by itself, character in a compound token.)
MORPHEMES = {
    '掌': (-6.3, -2.1),  # palm, grasp
    '鼓': (-4.1, -1.25),  # drum, encourage
    '虎': (-3.7, -1.1),  # tiger
    '鼎': (-3.3, -1.5),  # cauldron
    '赞': (-2.6, -1.3),  # praise
    '贊': (-2.7, -1.3),
    '讚': (-1.0, -0.5),
    '舞': (-2.45, -1.9),  # dance
    '卦': (-2.3, -0.7),  # divination hexagram
    '屌': (-1.8, -0.7),
    '鬼': (-1.1, -0.3),  # ghost
    '鼠': (-0.9, -0.3),  # mouse
    '龙': (-0.7, -0.3),
    '龍': (-0.7, -0.3),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    tail, previous = (b'', '') if initial else carry[1:3]
    position = 0 if initial else carry[3] + 1
    raw = prefix.token_bytes[-1]
    word = prefix.token_strings[-1].strip()
    joined = tail + raw
    value = -0.002
    for character, (alone, compound) in MORPHEMES.items():
        at = joined.rfind(character.encode())
        if at >= 0 and at + len(character.encode()) > len(tail):
            # A split character completed by this token is like a single one.
            single = word == character or '\ufffd' in word
            value = min(value, alone if single else compound)
    if word.startswith('掌握'):
        value = -4.2
    elif word == '手掌':
        value = -3.4
    elif word == '虎' and previous.endswith('白'):
        value = -4.8
    elif word == '掌控':
        value = -2.0
    elif word == '掌声':
        value = -1.0
    elif word == '拇指':
        value = -2.0
    if word.lower().strip('._/-') in ('thumb', 'thumbs'):
        value = -0.55 if word.lower().endswith('s') else -1.0
    elif word == 'đ':
        value = -3.0 if raw.startswith(b' ') else -0.7
    elif word == 'Đ':
        value = -0.85 if raw.startswith(b' ') else -0.3
    elif word == '두':
        value = -1.35
    if b'\xf0\x9f\x91\x8d' in joined:  # thumbs-up, including split bytes
        value = -3.4
    dot_run = word == '··' and (initial or carry[4])
    if dot_run:
        value = 2.5
    if position == 1 and previous == '1' and word == '2':
        value = 2.77  # the second digit of a document beginning with 12
    if word == '**' and previous == '.' and prefix.position >= 2:
        if prefix.token_strings[-3].strip().isdigit():
            value = 1.1  # opening bold after a numbered Markdown item
    if initial and value > -0.5 and word != '··':
        if not word:
            value = 0.5 if b'\n' in raw else 0.23
        elif word.isdigit():
            value = 0.36
        elif raw.startswith(b' ') and word.isalpha():
            value = 0.06
        elif word.isascii() and word.isalpha():
            value = 0.26
        else:
            value = 0.3
        if word == 'var':  # JavaScript variable-declaration keyword
            value = 2.18
        elif word == '#':
            value = 0.97
        elif word == '.' and raw.startswith(b' '):
            value = 2.62
        elif word.startswith('<|'):
            value = 1.71 if word == '<|endoftext|>' else -0.08
    return (doc, joined[-3:], word, position, dot_run), value

programs.haiku:
"""layers.1.mlp.down_proj:2267 - a lexical detector for a few Chinese (and Vietnamese/Korean)
single-character tokens, plus a small positive offset at the start of each document.

What it does: this component goes strongly negative on a short, scattered list of tokens.
The biggest are 掌 (palm; about -6), 鼓 (drum / encourage; about -4), 虎 (tiger; about -3.7),
掌握 (grasp / master; about -4), 舞 (dance; about -2.4), 鼎 (tripod; about -3), 赞 (praise;
about -2.5) and the Vietnamese token " đ" (about -3). Smaller negatives cover related words
(鼓励, 鼓舞, 赞扬, 点赞, 舞蹈, 跳舞, thumb, 拳, 颂) and a few more single characters. The
values are the mean activation each token had over ~12,000 training rows. Every other token
gets 0. The first token of each document (no context yet) gets +0.2, the average there.

What it leaves out: most of the variance is a diffuse layer of small (|act| < 0.2) values on
ordinary tokens, which no short concept captures, so this program explains only part of it.
"""

READS = ()

HAND_APPLAUSE = {  # palm, grasp, drum/encourage, praise, fist, thumb
    "掌": -6.2, "掌握": -4.1, "握": -1.6, "鼓": -4.0, "鼓励": -1.1, "鼓舞": -1.6,
    "赞": -2.5, "赞扬": -1.4, "点赞": -1.2, "颂": -0.9, "拳": -0.5,
    " thumb": -0.9, "thumb": -1.8, " thumbs": -0.5,
}
DANCE = {"舞": -2.4, "舞蹈": -2.0, "跳舞": -1.5}
TIGER_ZODIAC = {"虎": -3.7, "龙": -0.6, "龍": -0.6, "鼠": -1.0}
OTHER = {"鼎": -3.0, "卦": -2.0, " đ": -3.0, "두": -1.4, " 두": -1.4, "武汉": -1.3, "顶": -0.5}
TABLE = {**HAND_APPLAUSE, **DANCE, **TIGER_ZODIAC, **OTHER}
DOC_START = 0.2  # the first token of a document has no earlier context


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    if len(docs) == 1 or docs[-1] != docs[-2]:  # first token of a document (or of a row)
        return None, DOC_START
    return None, float(TABLE.get(prefix.token_strings[-1], 0.0))

programs.sol:
"""Token-level preferences for mathematical notation and explicit conclusions.

Arrows, relations, roots, and 'thus/therefore/hence' are the strongest cues.
There are smaller responses to object-opening quotes, comments, deep Markdown
headings and incomplete UTF-8 characters. TeX commands are distinguished from
ordinary words by their preceding backslash. A separate first-token baseline
handles absent left context. No other model values are read.
"""
import codecs
import unicodedata as ud

READS = ()


def local_value(token):
    word = token.strip()
    lower = word.lower()
    if lower in {'thus', 'therefore', 'hence'}:
        return 0.54 if word[:1].isupper() else 0.34
    if lower == 'consequently':
        return 0.20
    if lower in {'so', 'implies', 'imply'}:
        return 0.07
    if word in {'{"', "{'"}:
        return 0.32
    if word == '///':
        return 0.34
    if word == '-->':
        return 0.19
    if word and set(word) == {'#'} and len(word) >= 4:
        return 0.27
    if word in {'->', '=>'}:
        return 0.09
    if word == 'sqrt':
        return 0.30
    if len(word) == 1:
        name = ud.name(word, '')
        if word in '⇒⇔∴∵':
            return 0.87
        if 'ARROW' in name:
            return 0.67
        if word in '√≈':
            return 0.81
        if word in '×÷±∓≠≤≥∈∉':
            return 0.68
        if word in '≡∼∞':
            return 0.53
        if word == '−':
            return 0.53
        if ud.category(word) == 'Sm' and ord(word) > 127:
            return 0.30
        if word == '°':
            return 0.32
        if word in '′″':
            return 0.71
        if word == '§':
            return 0.52
        if 'GREEK' in name and ud.normalize('NFD', word) != word:
            return 0.42
    return 0.006 if token.isspace() else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    pending, previous = (b'', '') if first else carry[1:]
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    joined = pending + raw
    decoded, consumed = codecs.utf_8_decode(joined, 'replace', False)
    next_pending = joined[consumed:]
    value = local_value(token)

    if '\ufffd' in token:
        stripped = raw.lstrip()
        # UTF-8 prefixes of the Mathematical Operators and Arrows blocks.
        math_prefixes = (b'\xe2\x86', b'\xe2\x87', b'\xe2\x88',
                         b'\xe2\x89', b'\xe2\x8a', b'\xe2\x8b')
        if stripped in math_prefixes:
            value = 0.40
        elif stripped and 0x80 <= stripped[0] < 0xc0:
            value = 0.21 if len(stripped) == 1 else 0.02
            # A completed mathematical symbol can identify a byte fragment.
            completed = local_value(decoded)
            if completed >= 0.30:
                value = completed
        elif raw.startswith(b' '):
            # General Punctuation fragments and Greek letter lead bytes.
            if stripped in (b'\xe2\x80', b'\xe2\x81'):
                value = 0.39
            elif stripped in (b'\xce', b'\xcf'):
                value = 0.24
            else:
                value = 0.10

    if previous.endswith('\\'):
        command = token.strip()
        if command in {'le', 'leq', 'ge', 'geq', 'neq', 'approx'}:
            value = 0.75
        elif command in {'in', 'notin', 'sqrt'}:
            value = 0.61
        elif command in {'times', 'rightarrow', 'leftarrow'}:
            value = 0.49

    if first:
        if token.startswith('<|'):
            value = -0.06
        elif token.isascii() and any(c.isalpha() for c in token):
            value -= 0.28
    return (document, next_pending, token), value

programs.haiku:
"""Layer-1 MLP down-projection component 2268, predicted from the current token.

What it does, in plain terms: this component writes a signal into the residual stream that
is large and positive on a few kinds of token that show up in reasoning and technical text,
and slightly negative on the first token of each document. Its prediction, per token:

- first token of a document (a row start, or a new document packed into the row): -0.18
  (the model has no left context there, and the component is reliably negative);
- math and logic operator symbols (→ ⇒ ≈ √ × ÷ ± − ≤ ≥ ≠ ∈ ∞ ≡): +0.7, the strongest and
  most reliable trigger;
- other check-mark-like or technical symbols (✓ ✗ ° § € „ ¶ † © ® ′ ″): +0.3;
- consequence connectives that open a conclusion (Thus, Therefore, Hence, and their Chinese,
  Japanese equivalents 因此 所以 故 ので なので): +0.5;
- code and markup openers (`{"`, `///`, `sqrt`, `-->`, `import`): +0.25;
- accented modern Greek letters (ά έ ή ί ό ύ ώ) and ω, χ: +0.45;
- a fragment of a multi-byte character (decodes to U+FFFD): +0.07 if it starts a character,
  +0.16 if it continues one (the previous token was also a fragment);
- every other token: 0.

It needs no table of learned weights: each rule is a named set of characters or words.
Its ceiling is limited: the diffuse, token-specific variation on ordinary words is not captured.
"""

MATH_SYMBOLS = set("→⇒≈√×÷±−≤≥≠∈∞≡←∝∑∫")
OTHER_SYMBOLS = set("✓✗°§€„¶†©®☆′″")
CONSEQUENCE = {"thus", "therefore", "hence", "因此", "所以", "故", "ので", "なので"}
CODE_OPENERS = {'{"', "///", "sqrt", "-->", "import"}
ACCENTED_GREEK = set("άέήίόύώωχ")
REPLACEMENT = "�"

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    bare = text.strip().lower()
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        value = -0.18
    elif any(ch in MATH_SYMBOLS for ch in text):
        value = 0.7
    elif bare in CONSEQUENCE:
        value = 0.5
    elif any(ch in OTHER_SYMBOLS for ch in text):
        value = 0.3
    elif bare in CODE_OPENERS:
        value = 0.25
    elif any(ch in ACCENTED_GREEK for ch in text):
        value = 0.45
    elif REPLACEMENT in text:
        continuation = REPLACEMENT in prefix.token_strings[-2]
        value = 0.16 if continuation else 0.07
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A local detector of web destinations and repository artifacts.

Negative responses mark websites, repositories, and qualified web pages,
channels, stores, or presences. Physical-site qualifiers suppress that response;
printed-page references are positive. A few filename endings and formatting
patterns are recognized separately: an opening "Title:" is negative, while
repeated dot leaders and "View more" links are positive. Other text is zero.
State is only a short text tail, reset at document boundaries.
"""
import re

READS = ()
OWNERS = {'my', 'your', 'our', 'his', 'her', 'their', 'its', 'own', "'s", '’s'}
PLATFORMS = {'facebook', 'instagram', 'twitter', 'patreon', 'myspace', 'github'}
PHYSICAL = {
    'construction', 'historic', 'historical', 'archaeological', 'sacred',
    'binding', 'combining', 'injection', 'insertion', 'storage', 'well',
    'restriction', 'active', 'catalytic',
}
WEB = {'web', 'internet', 'online', 'official', 'dating', 'responsive'}
WEB_CONTEXT = re.compile(
    r'\b(?:website|web|online|internet|blog|http|https|browser|click|link|'
    r'html|wordpress|drupal|seo|hosting|facebook|twitter|youtube)\b'
)


def response(token, before, position):
    w, left = token.strip().lower(), before.lower()
    if token == '··' and before.endswith('··'):
        return 1.68
    if w == 'more' and left.endswith('view'):
        return 2.8 if token.startswith(' ') else 0.8  # an expand-details link
    if token == ':' and position < 3 and before.endswith('Title'):
        return -8.0

    # Endings of common repository filenames, including split tokens.
    if w == 'file' and not token.startswith(' '):
        if left.endswith('docker'):
            return -4.5 if before.endswith('docker') else -6.2
        return -5.4 if left.endswith('make') else 0.0
    if w == 'ignore' and left.endswith(('docker', 'git')):
        return -3.9 if left.endswith('docker') else -2.6
    if w == 'pm' and left.endswith(('pn', '.n')):
        return -4.4  # pnpm paths and .npm configuration
    if w == 'om' and left.endswith(('/p', '.p')):
        return -3.6  # Maven pom files
    if w == 'po' and left.endswith('re'):
        return -6.2  # split repo in a path/name
    if w in {'.github', '/www', '.yml', '.json'}:
        return -0.35 if w == '.json' else -0.75

    # Common non-English words for sites and pages.
    if w in {'网站', '網站', '官网', '官方网站', '站点', 'サイト'}:
        return -1.25
    if w in {'页面', '网页', '網頁', '主页', 'ページ', '페이지'}:
        return -2.2
    if w in {'сайт', 'сайта', 'сайте', 'сайты'}:
        return -1.7
    if w in {'страницу', 'страниц', 'страницы', 'pagina', 'página'}:
        return -2.3

    nouns = {'website', 'websites', 'webpage', 'webpages', 'homepage', 'site',
             'sites', 'page', 'pages', '-page', 'repository', 'repo', 'blog',
             'store', 'channel', 'presence'}
    if w not in nouns:
        return 0.0
    match = re.search(r"([\w]+|['’]s)\W*$", left)
    prev = match.group(1) if match else ''
    context = bool(WEB_CONTEXT.search(left[-120:]))

    if w in {'website', 'websites', 'webpage', 'webpages', 'homepage'}:
        if w == 'homepage':
            return -5.6
        if w in {'websites', 'webpages'}:
            return -1.3
        if prev == 'own':
            return -6.3
        if prev in OWNERS:
            return -4.8
        return -4.1 if w == 'webpage' else -3.25
    if w in {'repository', 'repo'}:
        if token == 'Repository':
            return -0.15  # a class-name suffix, not a web destination
        if prev in {'git', 'github', 'software'}:
            return -4.8
        if left.rstrip().endswith('='):
            return -0.9
        return -3.6 if w == 'repo' and prev in {'the', 'this'} else -2.5
    if w == 'blog':
        return -2.4 if prev in OWNERS else -0.65
    if w in {'site', 'sites'}:
        plural = w == 'sites'
        if prev in PHYSICAL:
            return 0.0
        if plural and prev == 'web' and token.strip().istitle():
            return -4.7
        if prev in OWNERS:
            return -1.1 if plural else -4.8
        if prev in {'wordpress', 'drupal'}:
            return -6.2
        if prev in WEB:
            return -1.3 if plural else -4.0
        if context or prev == 'this':
            return -0.8 if plural else -2.8
        return -0.25 if plural else -1.0
    if w in {'page', 'pages', '-page'}:
        plural = w == 'pages'
        if prev in PLATFORMS or prev in {'home', 'landing', 'product', 'fan'}:
            return -5.8 if plural else -7.2
        if w == '-page' and prev == 'main':
            return -4.3
        if prev in {'web', 'wordpress', 'drupal'}:
            if token.strip() == 'Page':
                return -5.4
            return -1.7 if plural else -4.0
        if prev in OWNERS or prev in {'this', 'that', 'notre'}:
            return -2.0 if plural else -4.0
        if left.endswith('pre-order'):
            return -1.4 if plural else -3.6
        if prev in {'about', 'login', 'archive', 'error', 'front', 'discussion'}:
            return -3.2
        if prev == 'me' and left.endswith('about me'):
            return -6.0
        if prev in {'int', 'var', 'const', 'return', 'function'}:
            return 0.3
        if prev == 'shows':
            return 5.3  # "this preview shows pages ..."
        if prev in {'first', 'last', 'next', 'previous', 'following', 'see'}:
            return 2.4
        if prev in {'printed', 'document'}:
            return 3.0
        if prev == 'per' or prev.isdigit():
            return 1.4 if plural else 0.4
        if context:
            return -1.0 if plural else -2.0
        if prev in {'on', 'in', 'from', 'at', 'of', 'through'}:
            return 1.1
        return 0.7 if plural or token.strip().istitle() else -0.3
    if w == 'presence':
        return -6.4 if prev in {'online', 'web'} else 0.0
    if w == 'store':
        if prev in {'online', 'web', 'ecommerce'}:
            return -8.0
        if prev in {'app', 'play', 'microsoft', 'etsy', 'shopify'}:
            return -4.8
        if prev in OWNERS:
            return -3.4
        return 0.2 if prev in {'to', 'can', 'will', 'and', 'only'} else -0.4
    if w == 'channel':
        return -5.4 if prev == 'youtube' else (-1.6 if prev == 'telegram' else 0.0)
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, before, position = carry
    value = response(token, before, position)
    return (doc, (before + token)[-256:], position + 1), value

