"""v3: square and angle brackets that open a new item are negative; comparisons are not."""
READS = ()
SQUARE = {"[", " [", "[[", "([", " ([", "#[", " #[", "][", " [\n", "[\n"}
ANGLE = {"<", " <"}
def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.2
    prev = prefix.token_strings[-2]
    s = prev.strip()
    if tok in ANGLE and s in ("include", "#include"):
        return carry, -3.0
    if tok in SQUARE:
        if prev.endswith("\n"):
            return carry, -0.8
        if s == "" or s[-1:] in ":(,=\"'{[;>-+*/&|!?." :
            return carry, -0.45
        if s.isalnum() and len(s) <= 2:
            return carry, -0.1
        return carry, -0.2
    if tok in ANGLE:
        if prev.endswith("\n") or s == "" or s[-1:] in ":(,=\"'{[;>-+*/&|!?.":
            return carry, -0.5
        if s.isalnum() and len(s) <= 2:
            return carry, 0.15
        return carry, -0.2
    return carry, 0.0

programs.sol:
"""A partial model of familiar expression endings, not a token lookup.

Dictionary-listed English phrases and split Chinese/Japanese dictionary words
receive negative contributions. Written conventions (format arguments, ordinal
suffixes, tag names and annotations) get separate corrections. Direction words,
byte fragments, check marks and repeated middle dots supply simple shape priors.
The many remaining token-specific differences are deliberately not represented.
"""
import re
import regex
from functools import lru_cache
import wordnet
import cedict
import jmdict

READS = ()
PREPOSITIONS = set(
    "at by for from in into of on onto over per through to under with without "
    "within upon across after before between beyond about against among "
    "around as during off out up down".split()
)
DIRECTIONS = set(
    "left right up down above below front back forward backward north south "
    "east west inside outside".split()
)
LOCATIVE_PREPOSITIONS = {
    "at", "by", "for", "from", "in", "into", "of", "on", "over",
    "through", "to", "under", "with", "without", "upon", "before", "after",
}
PLACES = set(
    "here there home abroad back forth ahead away nowhere somewhere anywhere "
    "everywhere upstairs downstairs indoors outdoors".split()
)

@lru_cache(maxsize=100000)
def phrase_parts(phrase):
    return wordnet.parts_of_speech(phrase)

@lru_cache(maxsize=100000)
def east_asian_word(word):
    return bool(cedict.glosses(word)), bool(jmdict.glosses(word))

# Each rule recognizes a conventional written ending.
ENDING_RULES = (
    ('%[-+#0-9.]*[sdifegvqxw]$', -1.302),  # format specifier
    ('\\d(?:st|nd|rd|th)$', -0.596),  # ordinal suffix
    ('</[A-Za-z][A-Za-z0-9]*$', -0.728),  # closing html tag
    ('<[A-Za-z][A-Za-z0-9]*$', -0.140),  # opening html tag
    ('@[A-Za-z_][A-Za-z_0-9]*$', -0.161),  # annotation
    ('(?<![\\w.])@[A-Z][A-Za-z0-9_]*$', -0.119),  # annotation capital
    ('```[A-Za-z]+$', -0.304),  # fence language
    ('\\\\(?:begin|end)\\{[a-z]+$', -0.556),  # latex environment
    ('(?:text|application|image)/[a-z]+$', -0.328),  # mime subtype
)

PHRASE_CORRECTIONS = (
    ('noun', -0.306),
    ('verb', -0.352),
    ('adjective', -0.341),
    ('adverb', -0.331),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    previous_bytes = b"" if carry is None or carry[0] != doc else carry[1]
    tail_bytes = (previous_bytes + raw)[-400:]
    tail = tail_bytes.decode("utf-8", "replace")
    result = (doc, tail_bytes)
    value = -0.002

    # Fragmented Unicode characters are distinguishable without token IDs.
    if "\ufffd" in token:
        value -= 0.083
    if raw and 128 <= raw[0] < 192:
        value -= 0.197
    try:
        raw.decode("utf-8")
    except UnicodeDecodeError as error:
        if error.reason == "unexpected end of data":
            value += 0.115

    s = token.strip()
    if s and all(ch in "✓✔✗✘" for ch in s):
        value -= 0.560
    if len(s) > 1 and set(s) == {"·"}:
        value += 0.742
    for pattern, correction in ENDING_RULES:
        if re.search(pattern, tail):
            value += correction

    # Dictionary suffixes count only when made entirely of East Asian letters.
    if regex.search(r"[\p{Han}\p{Hiragana}\p{Katakana}]$", tail):
        chinese = japanese = False
        for length in range(2, 5):
            word = tail[-length:]
            if len(word) != length:
                continue
            if len(word.encode("utf-8")) <= len(raw):
                continue
            if not regex.fullmatch(
                r"[\p{Han}\p{Hiragana}\p{Katakana}]+", word
            ):
                continue
            cn, jp = east_asian_word(word)
            chinese |= cn
            japanese |= jp
        value -= 0.175 * chinese + 0.122 * japanese

    if not re.fullmatch("[A-Za-z]+", s):
        return result, float(value)
    w = s.lower()
    words = re.findall(r"[A-Za-z]+", tail)
    previous = words[-2].lower() if len(words) > 1 else ""
    if w in DIRECTIONS:
        value -= 0.257
    if previous in PREPOSITIONS:
        value -= 0.032
    if previous == "as" and w.endswith("ed"):
        value -= 0.268
    if previous == "or" and w in {"not", "else", "otherwise"}:
        value -= 0.697
    if previous in LOCATIVE_PREPOSITIONS and w in PLACES:
        value -= 0.643
    if previous == "no" and w in {"one", "body", "more"}:
        value -= 0.317
    if tail.lower().endswith(("each other", "one another")):
        value -= 0.746

    ending = re.search(r"([A-Za-z]+(?: +[A-Za-z]+){1,3})$", tail)
    found = set()
    longest = 0
    if ending:
        ws = ending.group().lower().split()
        for length in range(2, len(ws) + 1):
            parts = phrase_parts(" ".join(ws[-length:]))
            if not parts and length == 2:
                for base in wordnet.base_forms(ws[-2], "verb"):
                    parts |= phrase_parts(base + " " + ws[-1])
            if parts:
                found.update(parts)
                longest = length
        # Allow a determiner or adjective between a preposition and its noun.
        if len(ws) >= 3:
            modifier = ws[-2] in {"a", "an", "the"}
            modifier |= "adjective" in phrase_parts(ws[-2])
            if modifier:
                if "adverb" in phrase_parts(ws[-3] + " " + ws[-1]):
                    value -= 0.154
    if found:
        value += 0.235
        for part, correction in PHRASE_CORRECTIONS:
            if part in found:
                value += correction
        if longest >= 3:
            value -= 0.287
    return result, float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 2272: a weak lexical feature.

What it does: it is mostly silent, but it dips negative on a few kinds of token.
  * Directional / position particles that complete phrasal verbs or adverbial
    phrases: back ("come back"), up ("pick up"), off, right, left, down, top,
    front, past, home ("at home"), away, around, side.            about -0.4
  * Idiom-final words of fixed expressions: time ("in time", "one at a time"),
    best ("at best"), own ("on my own"), mind ("in mind"), rest, end, way, hand, next.
                                                                    about -0.3
  * Some tech / code words that show up as tokens: Override, PASS, matrix, test(s),
    mut, div, usb, usr, bin, javascript, html, rust.                about -0.25
  * A lone non-Latin character (one CJK ideograph, kana, Hangul, Thai, or a
    half-written UTF-8 byte fragment, shown as U+FFFD).             about -0.12
  * Chat delimiters <|im_start|> / <|im_end|> are slightly positive (+0.15).
Everything else is predicted as 0 (the component's typical value).

Why: the component's activation is a per-token lexical signal with a long tail, and
no single concept covers it. These groups are the largest concentrated pieces that a
person can name. On 4k held-out training rows this program explains about 4% of the
activation variance. A per-token table of the ~1000 most informative tokens would
explain roughly 13%, but it would be a list of arbitrary token ids, so it is not used.
"""

import unicodedata

READS = ()

DIRECTIONAL = {
    "up", "down", "back", "left", "right", "off", "top", "front", "past",
    "home", "away", "around", "side",
}
IDIOM_FINAL = {"time", "best", "own", "mind", "rest", "end", "way", "hand", "next"}
TECH = {"override", "pass", "matrix", "test", "tests", "mut", "div", "usb", "usr",
        "bin", "javascript", "html", "rust"}
CHAT_DELIMITERS = {"<|im_start|>", "<|im_end|>"}


def lone_non_latin(text):
    """True for a one-character token outside Latin script, or a broken UTF-8 fragment."""
    if "�" in text:
        return True
    body = text.strip()
    if len(body) != 1 or body.isascii():
        return False
    return ord(body) > 0x2FF and not unicodedata.category(body).startswith("P")


def predict_token(text):
    word = text.strip().lower()
    if word in DIRECTIONAL:
        return -0.4
    if word in IDIOM_FINAL:
        return -0.3
    if word in TECH:
        return -0.25
    if text in CHAT_DELIMITERS:
        return 0.15
    if lone_non_latin(text):
        return -0.12
    return 0.0


def step(carry, prefix, upstream):
    # Each position depends only on the token being read, so no carry is needed.
    return carry, float(predict_token(prefix.token_strings[prefix.position]))

programs.sol:
"""A partial lexical and document-opening surrogate.

The largest rule is negative for Chinese 述 (state/narrate), with a
smaller negative response for compounds containing it. English describing
language is positive. Chinese 呼 (call) is negative; split 接头/出头
(joint/emergence) are positive. Additional small rules cover repeated
middle dots, the reasoning opener, and grammatical/code word classes.
Declaration words are especially positive at the beginning of a document;
temporal connectives are especially negative there. Other words stay near
zero. These rules do not explain all of the component's lexical variation.
"""
from functools import lru_cache
import wordnet

READS = ()

@lru_cache(maxsize=4096)
def lexical_value(text):
    if text == '··':
        return 0.38
    if text == '<think>':
        return 0.18
    if text == '述':
        return -3.6
    if '述' in text:
        return -1.2
    if text == '呼':
        return -0.6
    if text == '头':
        return 0.05
    word = text.strip().lower()
    if word.isascii() and word.isalpha():
        bases = set(wordnet.base_forms(word)) | {word}
        if 'describe' in bases:
            return 0.125
        if 'expression' in bases:
            return 0.10
        if bases & {'state', 'say'}:
            if word == 'said' or word.endswith('ed'):
                return 0.085
            return 0.02
    return -0.001


# Each group is a familiar grammatical or programming-language category.
# The two numbers are its opening-of-document and ordinary-position values.
WORD_CLASSES = (
    ('import export package #include', 0.51, -0.012),
    ('int string float double char bool boolean', 0.93, -0.008),
    ('def function', 1.37, -0.033),
    ('class struct interface enum type', 0.40, -0.009),
    ('before after since until during', -0.89, -0.013),
    ('here there front back behind', -0.20, -0.028),
    ('at in on by to from of with for as into over under through '
     'between about without within', -0.11, -0.003),
    ('each every all any some many most few both several', 0.30, -0.003),
)
WORD_CLASSES = tuple((frozenset(words.split()), first, later)
                     for words, first, later in WORD_CLASSES)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if start else prefix.token_strings[-2]
    if text == '··' and not start and previous != '··':
        return None, 0.03
    if text == '头' and previous.endswith(('接', '出')):
        return None, 1.8
    word = text.strip().lower()
    for words, first, later in WORD_CLASSES:
        if word in words:
            return None, first if start else later
    if start and text.isdigit():
        return None, 0.18
    return None, lexical_value(text)

"""Approximate responses to code syntax and indentation from recent text.

Strongest on quoted property separators (especially a name field), line-start
conditionals, and even-width indentation, including paragraph padding.
Smaller rules cover value quotes, declarations, and shell syntax.  Displayed
escapes, diff markers, and source line numbers are normalized.  Otherwise
predict near zero, with a negative baseline at a document's first token.
"""
import re

READS = ()

# Responses at a line boundary versus inside a line.
CONTROL = {
    'if': (1.16, 0.04), 'while': (0.87, -0.02),
    'for': (0.35, 0.0), 'switch': (0.82, 0.1),
    'elif': (0.65, 0.41), 'else': (0.14, 0.12),
}


def response(token, before, prev):
    # Keep actual and displayed (backslash-escaped) source code comparable.
    text = re.sub(r'\\+([nt])',
                  lambda m: '\n' if m[1] == 'n' else '\t', before)
    text = re.sub(r'(?m)^[+-](?=[ \t]|$)', '', text)
    text = re.sub(r'(?m)^ *[0-9]+\t', '', text)
    line = text.rsplit('\n', 1)[-1]
    start = not line.strip()
    word = token.strip(' \t')
    token = token.replace('\\', '') if '"' in token else token
    if token in ('":', '":"', "':", "':'"):
        if token.endswith(('"', "'")):
            return 0.62
        if prev == 'name':
            return 1.58
        return 1.08
    if token == ':':
        if (re.search(r'(?:[,{]\s*|\n[ \t]+)[$\w]+$', text)
                and text.rfind('{') > text.rfind('(')):
            return 1.04
        return 0.04
    if word in ('if', 'while', 'for', 'switch', 'elif', 'else'):
        # Newline, indentation, or a shell-escaped tab before a keyword.
        if word == 'if' and re.search(r'\belse\s*$', text):
            return 1.35
        if start or token.startswith('\t') or prev.endswith('``'):
            return CONTROL[word][0]
        return CONTROL[word][1]
    if token and not token.strip(' \t'):
        spaces = len(token) - len(token.rstrip(' '))
        if start and spaces and spaces % 2 == 0:
            if spaces == 4:
                if text.rstrip().endswith((';', '{', '/*')):
                    return 0.95
                return 0.85
            return 0.19 if spaces >= 16 else 0.42
        return 0.0
    if token in (' "', " '"):
        if prev in ('":', "':", ':', ' :'):
            if re.search(r"[\"']type[\"']:$", text):
                return 1.18
            if re.search(r"[\"']command[\"']:$", text):
                return 0.79
            return 0.34
        if prev.strip() in ('=', '==', '===', '<<', '=>'):
            return 0.23
    if token == '="':
        return 0.18
    if token == ' =>':
        return 0.94 if prev.endswith(("'", '"')) else 0.28
    if token.lstrip(' ') in ('{', '{\n', '{\n\n', '{\r\n'):
        if prev.strip() in ('import', 'export', 'const', 'type', 'param'):
            return 0.96
        if re.search(r'\b(class|interface|namespace|enum|struct)\b[^;{}]*$', text):
            return 0.74
    if token == ' *' and re.search(r'/\*\s*$', text):
        return 0.82
    if (prev == ' -' and re.fullmatch('[a-zA-Z]+', token)
            and re.search(r'\b(cat|grep|ls|git|python[23]?|go|cargo|npm|'
                          r'pip[23]?|sed|find|head|tail|curl|tar|rm|cp)\b', line)):
        return 0.97
    if token in (' &&', ' ||'):
        return 0.23 if token == ' &&' else -0.08
    if token in (' and', ' or', ' not') and re.search(r'^\s*(if|while|elif)\b', line):
        return 0.56
    if word in ('test', 'run', 'build', 'install', 'uninstall'):
        if prev.strip() in ('go', 'cargo', 'npm', 'pip', 'pip3'):
            return 1.09
    if token == '#!':
        return 1.5
    if token == 'php' and prev == '<?':
        return 1.39
    if token == '#"' and prev.endswith('r'):
        return 2.1
    if word == 'EOF' and re.search(r'<<\s*[\'\"]?$', text):
        return 2.47
    return -0.19 if not before else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, prev = '', ''
    else:
        _, before, prev = carry
    token = prefix.token_strings[-1]
    value = response(token, before, prev)
    return (doc, (before + token)[-256:], token), value

programs.haiku:
"""Layer 1, MLP down-projection, component 2274: a code-syntax detector.

It is near zero on ordinary prose and fires on the punctuation and keywords that structure
code, most strongly inside an open brace { ... } (an object literal or a block):
  - the colon or quote-colon that separates a key from its value: `type: X`, `"name": "x"`,
    `'message' => ...`                                         (about 1.2 inside braces)
  - the colon itself, inside braces                             (about 0.8)
  - the `if` that starts a statement in code                    (about 1.2 inside braces, 0.35 otherwise)
  - an opening quote in code, and indentation                   (about 0.3 to 0.6)
  - the heredoc marker `EOF` in `cat << 'EOF'`                  (about 1.5)
Everything else predicts 0. The values are the mean activations of those classes on
training text; the program is a lookup over a few token classes plus one context check.
"""

KEY_SEPARATORS = {'":', "':", ':"', '":"', '\\":', ' =>'}
IF_WORDS = {' if', '\tif', 'if'}
READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = s[-1]
    recent = ''.join(s[-150:])
    inside = recent.count('{') > recent.count('}')     # inside an open { ... }
    tail = recent[-120:]
    code = tail.count('(') + tail.count(';') + tail.count('=') > 0
    if t in KEY_SEPARATORS:
        v = 1.2 if inside else 0.8
    elif t == ':':
        v = 0.8 if inside else 0.08
    elif t in IF_WORDS:
        v = 1.2 if inside else 0.35
    elif t == ' "' or t == " '":
        v = 0.3 if inside else 0.07
    elif t == '    ':
        v = 0.6
    elif t == '  ':
        v = 0.45 if inside else 0.25
    elif t == 'EOF':
        v = 1.5 if code else 0.8
    else:
        v = 0.0
    return carry, v

programs.sol:
"""Approximate a local EW-versus-W spelling contrast.

Short EW pieces, especially HEW, CHEW and EWS, get positive values.
NEW and familiar phrases such as 'a few' are weaker. Bare W pieces in
some consonant/acronym contexts, and W after %, get negative values.
Selected suffixes inherit EW's signal; a split Russian loanword is also
recognized. Long alphanumeric runs are damped. State resets by document.
"""

READS = ()


def spelling(token, previous):
    s = token.strip()
    word = s.lower()
    adjacent = bool(token and token[0].isalpha() and previous
                    and previous[-1].isalpha())
    last = previous[-1] if adjacent else ''
    if (word == 'w' and previous.endswith('%')) or word == '%w':
        return -4.5
    if word == 'chewing':
        return 3.5
    if 'ew' in word:
        i = word.index('ew')
        tail = len(word) - i - 2
        if word.startswith('renew'):
            return 3.1 / (1 + 0.3 * (len(word) - 5))
        if word == 'few':
            p = previous.strip()
            if p == 'a':
                return 0.05
            if p.lower() in ('the', 'very', 'too', 'so', 'how', 'as', 'only'):
                return 0.4
            return 0.7 if p == 'A' else 3.0
        if word.startswith('new'):
            return 6.0 if adjacent and previous.lower().endswith('re') else 0.1
        if i == 0:
            if tail:
                if word in ('ewe', 'ewed') and last.lower() == 'h':
                    return 6.0
                return (6.5 if word == 'ews' else
                        4.2 if word in ('ewing', 'ewn') else 0.5)
            if (last.lower() in ('h', 't') or last == 'J'
                    or previous.strip().lower() == 'm'):
                return 7.5
            if last.lower() in ('e', 'g', 'j', 'b'):
                return 1.7
            if last.lower() == 'p':
                return 0.0
            return 4.0
        if i <= 2:
            consonant = word[i - 1]
            value = (6.0 if consonant == 'h' else
                     5.0 if i == 1 and consonant in 'dl' else
                     3.0 if consonant in 'sf' else
                     3.8 if consonant == 't' else
                     0.5 if consonant in 'nri' else 1.7)
            return value * 0.2 ** tail
        return 0.1
    if 'w' not in word:
        return 0.0
    if adjacent and word.startswith('w') and last.lower() == 'e':
        if last == 'E':
            if word == 'w':
                return 9.0
            if previous.strip() == 'E' and len(word) <= 5:
                return 6.0
            if word == 'ws':
                return 6.0
            return 4.0 if word == 'well' else 0.5
        if previous.lower().endswith('tre'):
            return 7.5 if len(word) <= 3 else 1.0
        return 1.5
    letters = ''.join(c for c in s if c.isalpha())
    if letters.lower() == 'w' and not token.startswith(' '):
        if last.lower() in ('b', 'd', 'g', 'p'):
            return -2.8
        if last.isupper():
            return -1.8
        if last and last.lower() not in 'rsyiu':
            return -0.6
        return -0.2 if not adjacent and not s.isalpha() else 0.0
    if s == 'AW' and last == 'U':
        return -4.5
    if word.endswith('qw'):
        return -4.5 if token.startswith(' ') else -1.5
    if len(letters) <= 3 and word.endswith(('dw', 'lw')):
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_value, run = '', 0.0, ''
    else:
        _, previous, previous_value, run = carry
    token = prefix.token_strings[-1]
    value = spelling(token, previous)
    # Final piece of the Russian loanword 'interview'.
    if token == 'ью' and run.lower().endswith('интерв'):
        value = 3.0
