    if token.lower() in ('s', 'es', 'ing') and previous.lower().endswith('ew'):
        value += 0.75 * max(0.0, previous_value)
    for char in token:
        run = (run + char)[-40:] if char.isalnum() else ''
    if len(run) >= 24:
        value *= 0.15
    return (doc, token, value, run), value

