"""The letter pair e-w in the current token, as it reads in the text.

Layer 1's MLP writes this component in response to spelling, not meaning:
  * an e-w pair that closes an unfamiliar word piece ('Hew', 'Chew', 'Renew', 'Mathews',
    'skew', 'gew'): clearly positive, about +1 on average and up to +8;
  * an e-w pair inside a longer piece ('ewhere', 'ewan'): weakly positive;
  * an everyday word with e-w (new, view, review, news, few): nearly zero;
  * a bare w or W with no e before it ('w', 'W', '/w', '-w'): weakly negative;
  * everything else, including words that merely contain w (with, was, we): zero.
The pair is read across the token boundary, so 'le' + 'wy' counts as 'e' then 'w'.
"""

READS = ()

COMMON_EW_WORDS = {
    "new", "news", "view", "views", "review", "reviews", "few", "fewer", "knew",
    "newer", "newest", "newly", "newspaper", "newsletter", "preview", "viewer",
    "viewing", "interview", "interviews", "renewal", "renewable", "reward", "flew",
    "jewelry", "somewhat", "framework", "newborn", "overview", "stewart",
}
BARE_W_TOKENS = {"w", "/w", "-w", "(w"}

PIECE_EW = 1.0    # unfamiliar piece closing with e-w or e-w-s
COMMON_EW = 0.15  # everyday word with e-w
INSIDE_EW = 0.2   # e-w inside a longer piece
BARE_W = -0.3     # a w with no e before it


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""
    joined = (before + tok).lower()
    start = len(before)
    word = tok.strip().lower()
    has_ew = any(
        joined[j] == "w" and j > 0 and joined[j - 1] == "e"
        for j in range(start, len(joined))
    )
    if has_ew:
        if word.endswith("ew") or word.endswith("ews"):
            return None, COMMON_EW if word in COMMON_EW_WORDS else PIECE_EW
        return None, INSIDE_EW
    if word in BARE_W_TOKENS:
        return None, BARE_W
    return None, 0.0

