import re

READS = ()


def underline_response(piece_length, run_length, title):
    """Use heading format and fragment length to set the spike amplitude."""
    if '{#' in title:
        if piece_length <= 1:
            return -4.8
        return -9.2 if piece_length < 15 else -5.9

    title = title.strip()
    heading = (bool(title) and title[0].isupper()
               and title[-1] not in '.,:;!?' and len(title) < 160)
    if piece_length == 0:  # newline closing an underline
        return -3.2 if heading else -1.0
    if run_length:
        if not any(ch.isupper() for ch in title):
            return -0.8
        if piece_length >= 16:
            return -1.0
        return -5.0 if run_length <= 32 else -2.3
    if piece_length < 6:
        return 0.0
    if not heading:
        return -1.0
    if len(title.split()) > 2:
        return -2.0
    return -6.0 if piece_length < 16 else -3.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    if fresh:
        line, previous, breaks = '', '', 0
    else:
        _, line, previous, breaks = carry
    token = prefix.token_strings[-1]
    stripped, before = token.strip(), line.strip()
    value = -0.2 if fresh and token.startswith(' ') else 0.0

    if stripped == '{' and '\n' in token and not before:
        declaration = re.search(r'\b(class|namespace|interface|struct)\b', previous)
        value = -1.6 if declaration else (-0.8 if not line else -0.4)
    if len(stripped) >= 2 and set(stripped) == {'^'}:
        value = -1.5
    if stripped == 'Posts' and not before:
        value = -1.3
    if stripped == ':' and before in ('Posts', 'Joined', 'Registered'):
        value = -0.7 if before == 'Registered' else -1.2
    if '\xa0' in token and before == '–':
        value = 3.1
    if stripped == 'b' and before == '+++':
        value = -2.0

