    mark = stripped[:1] or (before[:1] if '\n' in token else '')
    if mark in ('-', '=', '_') and breaks == 1:
        piece = not stripped or set(stripped) == {mark}
        run = bool(before) and set(before) == {mark}
        if piece and (not before or run):
            if mark == '_':
