        parts = (line + token).split('\n')
        previous, line = parts[-2].rstrip('\r'), parts[-1]
        tail = token.replace('\r\n', '\n').rstrip(' \t')
        breaks = max(1, len(tail) - len(tail.rstrip('\n')))
    else:
        line = (line + token)[-500:]
    return (doc, line, previous, breaks), float(value)

