DATE = {'date', 'time', 'created', 'modified', 'updated', '日期', '时间'}
DESCRIPTION = {'description', 'desc', 'brief', 'summary', 'fn', '描述', '说明'}
FILE = {'file', 'package'}
HEADER = {'copyright', 'project', 'function', 'purpose', 'email', 'version'}
TAG_VALUE = {'author': -9.4, 'date': -9.35, 'description': -4.87, 'file': -4.32}
COMMENT_VALUE = {'author': -7.8, 'date': -0.7, 'description': -1.59,
                 'file': -0.34, 'header': -2.22}


