    group = next((name for words, name in (
        (AUTHOR, 'author'), (DATE, 'date'), (DESCRIPTION, 'description'),
        (FILE, 'file'), (HEADER, 'header')) if field in words), None)
    tag = (word.startswith('@') or bool(re.search(r'(?<!@)@\s*$', line))
           or comment and bool(re.search(r'(?:^|[\s*])\\\s*$', line)))
