        elif comment and not clean:
            value = COMMENT_VALUE[group]
            if field == 'created' and token.strip()[0].isupper():
                value = -10.48
            elif field in {'modified', 'updated'}:
                value = -1.36
            elif token.strip()[0].isupper() and group in {'date', 'description'}:
                value = -3.1 if group == 'date' else -3.82
        elif group == 'description':
            value = -0.15
        elif group == 'author' and not clean:
