        value = -1.05
    if word in {'by', 'on', 'at'} and token[:1].isspace():
        if comment and re.fullmatch(r'(?:@author\s+)?Created', clean):
            value = -7.14 if word == 'at' else -15.38
        elif re.search(r'\bmodified\s*$', line, re.I):
            value = -6.06 if comment else -0.24
        elif word == 'on' and re.search(r'\bcreated by\b', line, re.I):
            value = -1.94
    if word in {'modified', 'updated', 'uploaded'} and line.lower().endswith('last'):
        value = -1.35
    if field == 'created' and line.endswith('File'):
        value = -2.21
    if word in {'description', 'name'} and line.endswith('File'):
        value = -7.08 if word == 'description' else -5.18
    if word == 'time' and comment and line.endswith('Created'):
        value = -9.05
    if word in {'name', 'doc', 'author'} and line.endswith('__'):
        value = -10.08 if word == 'author' else -0.52
    if word in {"'", '"'} and re.search(r'__author__\s*=\s*$', line):
