    if word in {':', '：'}:
        last = re.search(r'(\w+)\s*$', line)
        label = last.group(1).lower() if last else ''
        if clean == 'Title' and position == 1:
            value = 4.33
        elif label in AUTHOR | (DATE - {'modified', 'updated'}):
            explicit = (comment or clean.startswith('@'))
            value = -6.2 if explicit and re.fullmatch(r'@?\w+', clean) else -0.4
        elif label in DESCRIPTION:
            value = -3.98 if comment or clean.startswith('@') else -0.24
        elif label in HEADER | FILE:
