    if word == 'right' and line.endswith('Copy'):
        value = -3.6
    if word == 'usr' and line.endswith('#!/'):
        value = -1.64
    block = block and '*/' not in token
    line = (line + token).rsplit('\n', 1)[-1][-160:]
    return (doc, line, block, quote, position + 1), value

