"""A whitespace-boundary detector.

Separate space tokens in succession give a large positive response, especially
within a line rather than in indentation.  Padded comments and punctuation give
smaller responses.  Unmerged line breaks and null bytes after a single-space
token give negative responses.  Most ordinary text gives zero; the initial
end-of-text marker is also negative.  Weak token-specific effects are omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, indentation = '', True
    else:
        _, previous, indentation = carry
    text = prefix.token_strings[-1]
    spaces = len(previous) if previous and not previous.strip(' ') else 0
    horizontal = bool(previous) and not previous.strip(' \t\xa0')
    value = 0.0

    if first and text == '<|endoftext|>':
        value = -8.89
    elif text == ' ':
        if first:
            value = 0.78
        elif spaces == 1:
            value = 2.32 if indentation else 5.33
        elif spaces == 2:
            value = 0.21 if indentation else 2.30
        elif spaces == 3:
            value = -0.35 if indentation else 1.57
        elif spaces > 3:
            value = -0.16 if indentation else min(1.5, 6.0 / spaces)
        elif previous and not previous.strip('\xa0'):
            value = 2.4 if len(previous) == 1 else 1.0
        elif previous.endswith((' ', '\xa0')):
            value = 1.2
    elif text == '\xa0':  # A non-breaking space.
        if first:
            value = 0.88
        elif previous == '\xa0':
            value = 4.0
        elif previous and not previous.strip('\xa0'):
            value = 1.3
        elif spaces == 1:
            value = 3.4
        elif horizontal or previous.endswith((' ', '\xa0')):
            value = 1.8
        else:
            value = -0.2
