        value = -2.8
    elif text and not text.strip('\r\n') and horizontal:
        value = (-3.3 if '\xa0' in previous
                 else -1.8 - 0.03 * len(previous))
    elif text == ' \xa0' and previous.endswith('\xa0'):
        value = 1.7
    elif text == ' \n' or text == ' \r\n':
        value = 0.25
    elif text == ' \n\n':
        value = -0.13
    elif text.startswith(' ') and text.strip() and horizontal:
        body = text[1:]
        if indentation:
            if body.startswith(('//', '#')):
                value = 0.6 if spaces == 1 else 0.3
            elif body.startswith('\\'):
                value = 0.45 if spaces == 1 else 0.25
            elif body.startswith('`') and spaces == 1:
                value = 1.0
        else:
            if spaces == 1:
                strength = 1.0
            elif spaces == 2:
                strength = 0.7
            else:
                strength = 0.35
            if body.startswith('#'):
                value = 4.4 * strength
            elif body.startswith('//'):
                value = 3.1 * strength
            elif body.startswith('\\'):
                value = 1.9 * strength
            elif body.startswith('$'):
                value = 1.4 * strength
            elif body.startswith(('`', '|')):
                value = 1.1 * strength
            elif body.startswith(('-', '+', '*', '/', '^')):
                value = 1.65 * strength
            elif body.startswith(('{', '}', '(', ')', '[', ']')):
                value = 0.8 * strength
