from functools import lru_cache
import wordnet

READS = ()
TIME = {
    'second', 'minute', 'hour', 'day', 'week', 'month', 'year', 'night', 'time',
}
LENGTH = {'meter', 'metre', 'foot', 'inch', 'mile', 'centimeter', 'kilometer'}
MEASURE = {
    'gram', 'kilogram', 'ounce', 'pound', 'ton', 'litre', 'liter',
    'cup', 'teaspoon', 'tablespoon', 'pint', 'quart', 'mole',
    'unit', 'degree', 'percent', 'decimal',
    'piece', 'part', 'slice', 'item', 'portion',
    'dollar', 'euro', 'yuan', 'yen', 'rupee', 'ruble',
}
COUNTS = {
    'comment', 'vote', 'view', 'reply', 'thought', 'test', 'warning',
    'error', 'result', 'user', 'member', 'like', 'snapshot', 'review', 'answer',
}
