NUMBERED_BOOKS = {
    'John', 'Peter', 'Tim', 'Timothy', 'Samuel', 'Kings',
    'Corinthians', 'Thessalonians', 'Chronicles',
}

@lru_cache(maxsize=8192)
def kind(word):
    forms = set(wordnet.base_forms(word)) | {word}
    if forms & TIME:
        return 'time'
    if forms & LENGTH:
        return 'length'
    if forms & MEASURE or word == 'mol':
        return 'measure'
    if forms & COUNTS:
        return 'count'
    if word in {'g', 'kg', 'm', 'cm', 'ml', 'wt', 'min', 'qt'}:
