    if token.isascii() and token.isdigit():
        if previous.isdigit():
            number = number + token if number else ''
        else:
            # Decimal suffixes and digits in identifiers are not integer counts.
            valid = not previous or not (
                previous[-1].isalpha() or previous[-1] in '._'
            )
            number = token if valid else ''
            own_line = clean_line
    else:
        number = ''
    tail = token.rsplit('\n', 1)[-1]
    clean_tail = not tail.strip(' \t\r•+-|')
    clean_line = clean_tail if '\n' in token else clean_line and clean_tail
    return (doc, token, number, own_line, clean_line), value

programs.haiku:
"""Layer-1 MLP down_proj neuron 2281: a 'counted thing' detector.

The component goes negative on the word right after a small quantity when that word names
the thing being counted. The quantity is a standalone 0 or 1 (or the words no, one, two):
a forum or social counter ("0 answers", "1 vote", "16 views", "0 Comments"), a time span
("1 year", "3 days"), a measure ("1 cup", "1 meter"), or a test or build result ("5 tests",
"1 warning"), with the largest values for counters and the weakest for other words. The
same quantity also gives a negative value on the space token that comes before a number's
word, and "you guys", "we all" and numbered Bible books ("1 John", "2 Timothy") are negative.
The quantity 2 gives about half the value. Small effects: the first token of a document is
mildly negative, and the Chinese 这个/这 is mildly positive.
"""

READS = ()

CLASSES = {
    -4.0: "views view likes like comments comment votes vote answers answer reviews review "
          "ratings rating replies reply posts post thoughts followers",
    -2.0: "unit units item items file files package packages step steps children people "
          "person persons man men pair pairs member members mark marks solutions solution",
    -1.4: "year years day days week weeks month months hour hours hr hrs minute minutes "
          "min mins second seconds sec ms",
    -1.1: "cup cups tsp tbsp teaspoon teaspoons tablespoon tablespoons mole moles mol meter "
          "meters m liter liters l gram grams g kg km mile miles foot feet pound pounds quart "
          "qt gallon cubic decimal",
    -0.9: "tests test points point warnings warning errors error failed passed ignored "
          "filtered skipped failures",
}
VALUE = {w: v for v, ws in CLASSES.items() for w in ws.split()}
BIBLE_BOOKS = set("John Peter Timothy Tim Sam Samuel Kings Corinthians Cor Chronicles Chron "
                  "Thessalonians Thess Maccabees".split())
PRONOUNS = {"you", "we"}
DEMONSTRATIVE = {"这", "这个", "这一", "这份", "这一点", "那个", "這個", "這"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    cur = toks[t]
    if t == 0 or docs[t] != docs[t - 1]:
        return carry, -0.12                      # first token of a document
    prev = toks[t - 1].strip()
    before = toks[t - 2] if t >= 2 and docs[t - 2] == docs[t] else ""
    word = cur.startswith(" ") and cur[1:].isalpha()
    w = cur[1:].lower() if word else ""
    if prev in ("0", "1", "2") and not before.isdigit():
        if prev == "2" and cur.strip() == "":
            return carry, -0.3                   # a space before a counted word
        if prev == "2":
            return carry, 0.5 * VALUE.get(w, -0.2 if word else 0.0)
        if word and cur[1:] in BIBLE_BOOKS:
            return carry, -3.5                   # "1 John", "2 Timothy"
        if w in VALUE:
            return carry, VALUE[w]
        if word:
            return carry, -0.2
        if cur == " ":
            return carry, -0.7                   # a space before the counted word
        if cur in ("\n", "\n\n") and before.endswith("\n"):
            return carry, -1.5                   # a lone 0 or 1 on its own line
        if cur in ("/", ":"):
            return carry, 0.4                    # ratio or fraction: 1/2, 1:1
    if prev.lower() in ("no", "one", "two") and w in VALUE:
        return carry, 0.5 * VALUE[w]             # "no test", "one day"
    if prev.lower() == "no" and w in ("one", "two"):
        return carry, -3.0                       # "no one", "no two"
    if prev.lower() in PRONOUNS and w in ("guys", "all", "both", "two"):
        return carry, -2.5                       # "you guys", "we all"
    if cur in DEMONSTRATIVE:
        return carry, 0.28                       # Chinese 这个 after 我/那
    return carry, 0.0

programs.sol:
"""A partial predictor for rare glyph fragments and document openings.

炎 and 炎症 (fire/inflammation) receive a strong negative prediction.
Other rules recognize
single-byte pieces of Unicode characters: flag letters, Korean affricates,
polytonic Greek, private-use glyphs, miscellaneous symbols, and Han radicals.
Unfinished characters are classified from their permitted codepoint ranges,
not the next token. Code headers receive a negative document-start response.
Small corrections cover chat delimiters and Japanese grammatical particles.
Most positions receive only a small background value.
"""
import codecs
import regex as re
import unicodedata
from collections import Counter
from functools import lru_cache
import unihan

READS = ()
# Fixed chat protocol boundaries.
CHAT_BOUNDARIES = {
    '<|im_start|>': -0.02, '<|im_end|>': 0.046,
    '</tool_call>': 0.168, '<tool_response>': -0.075,
    '</tool_response>': -0.072,
}
JAPANESE_PARTICLES = {
    'の': 0.12,    # genitive
    'を': 0.096,   # accusative
    'が': -0.077,  # nominative
}
RADICAL_RESPONSE = {'sheep': -2.0, 'net': -1.4, 'hand': 0.6, 'tree': 0.6}
DECLARATIONS = {
    'int', 'float', 'double', 'char', 'void', 'bool', 'let', 'var',
    'const', 'function', 'class', 'def', 'import', 'package',
    'namespace', 'public', 'private', 'static', 'using', 'module',
    'export', 'from', 'struct', 'enum',
}


@lru_cache(maxsize=2048)
def unfinished_response(fragment, space_prefixed):
    """Classify the character range specified by an incomplete UTF-8 prefix."""
    length = 2 if fragment[0] < 0xE0 else 3 if fragment[0] < 0xF0 else 4
    missing = length - len(fragment)
    try:
        first = ord((fragment + b'\x80' * missing).decode('utf-8'))
    except UnicodeError:
        return 0.002
    width = 64 ** missing
    middle = first + width // 2
    if unicodedata.category(chr(middle)) == 'Co':
        return 0.002 if space_prefixed else 0.6
    if not space_prefixed:
        return 0.002
    if re.fullmatch(r'\p{Block=Miscellaneous_Symbols}', chr(middle)):
        return -2.5
    name = unicodedata.name(chr(middle), '')
    if name.startswith('HANGUL SYLLABLE J'):
        return 1.8
    if name.startswith('HANGUL SYLLABLE C'):
        return -0.8
    if re.fullmatch(r'\p{Block=Greek_Extended}', chr(middle)):
        names = [
            unicodedata.name(chr(c), '')
            for c in range(first, first + width)
        ]
        iota = sum('YPOGEGRAMMENI' in n for n in names)
        return -1.7 if iota > width / 2 else -0.25
    if re.fullmatch(r'\p{Script=Han}', chr(middle)):
        radicals = Counter(
            unihan.radical(chr(c)) for c in range(first, first + width)
        )
        radical, count = radicals.most_common(1)[0]
        if radical is not None and count >= width / 2:
            name = unihan.radical_name(radical)
            return RADICAL_RESPONSE.get(name, 0.002)
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    beginning = carry is None or carry[0] != doc
    previous, pending = (b'', b'') if beginning else carry[1:]
    token = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    decoded, used = codecs.utf_8_decode(pending + token, 'replace', False)
    pending = (pending + token)[used:]
    value = CHAT_BOUNDARIES.get(text, JAPANESE_PARTICLES.get(text, 0.002))
    if text in {'炎', '炎症'}:
        value = -4.0
    elif len(token) == 1 and 0x80 <= token[0] < 0xC0:
        if pending:
            value = unfinished_response(pending, previous.startswith(b' '))
        elif decoded:
            char = decoded[-1]
            if re.fullmatch(r'\p{Regional_Indicator}', char):
                value = 0.8
            elif not previous.startswith(b' '):
                name = unicodedata.name(char, '')
                if name.startswith('HANGUL SYLLABLE C'):
                    value = -0.45
    elif beginning or previous == b'<|endoftext|>':
        value = -0.19
        if text.isascii() and text.isalpha():
            value = -0.27
        elif text.isascii() and text.isdigit():
            value = -0.30
        elif text.isspace():
            value = -0.5 if '\n' in text else -0.13
        if re.fullmatch(r'/\*+\s*', text):
            value = -1.8 if '\n' in text else -1.2
        elif text in DECLARATIONS:
            value = -0.9
        elif text.strip() in {"'''", '"""'}:
            value = -1.6
        elif text == '#!/':
            value = -1.25
    return (doc, token, pending), value

"""A local agency / public-institution signal, with a few contrasting collocations.

Agency words are the strongest positive cue.  Public policy, law enforcement,
public health and schools also contribute, while 'common ratio/cause' are
negative.  Additional rules cover g-ending word fragments, a few place-name and size
collocations, Chinese civic terms, and Korean 공-/보- compounds. Repeated
middle dots are negative. Only the previous token is retained, resetting at
document boundaries. Unmatched positions are zero, except for a small negative
document-start baseline. This is a partial, local approximation.
"""

READS = ()

# Completions of 'public' referring to governmental responsibilities.
PUBLIC_FIELDS = {
    'safety': 4.6, 'law': 4.8, 'health': 2.3, 'policy': 2.3,
    'education': 2.7, 'school': 1.6, 'schools': 1.3,
    'security': 1.7, 'assistance': 3.5, 'administration': 1.0,
    'sector': 1.4, 'company': 1.5, 'insurance': 2.3,
    'office': 1.2, 'advocacy': 1.0,
    'service': -1.6, 'property': -1.3, 'account': -1.8,
    'information': -0.7, 'officials': -0.9,
}
COMMON = {
    'ratio': -5.0, 'cause': -3.5, 'law': 4.2, 'stock': 1.2,
    'knowledge': -2.5, 'pool': -1.8, 'usage': -1.9,
    'ground': -1.2, 'interests': -1.2, 'people': -1.2,
    'shares': -0.8, 'sense': -0.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = '' if carry is None or carry[0] != doc else carry[1]
    prev = previous.strip().lower()
    value = -0.24 if not previous and not token.startswith('<|') else 0.0

    if word in {'agency', 'agencies'}:
        value = 4.6 if previous[:1].isspace() and prev.isalpha() else 7.0
        if prev in {'intelligence', 'security'}:
            value = 1.9
        elif prev == 'news':
            value = 3.4
        elif prev == 'inter':
            value = 9.0
    elif (prev.endswith('ag') and word.startswith('enc')
          and token[:1].isalpha()):
        # A split agency/agence/agencia, including identifiers.
        value = 7.5
    elif prev in {'a', '_a', '-a'} and word in {'gency', 'gencies'}:
        value = 6.5
    elif prev == 'lang' and word == 'ley':
        value = 8.5  # Langley, the intelligence-agency metonym / surname.
    elif prev == 'law' and word == 'enforcement':
        value = 5.0 if previous.strip().islower() else 6.5
    elif prev == 'public':
        value = PUBLIC_FIELDS.get(word.lstrip('-'), 0.0)
        if word == 'law':
            value = 5.5 if token.strip().istitle() else 3.5
    elif prev == 'private' and word.lstrip('-') in {
        'sector', 'law', 'attorney', 'practice', 'health', 'insurance'
    }:
        value = 1.8
    elif prev == 'common':
        value = COMMON.get(word, 0.0)
    elif prev == 'big':
        if word in {'bang', 'league', 'time', 'city', 'business', 'idea', 'ideas'}:
            value = 2.0
        elif word in {'man', 'guy', 'sister', 'band', 'company', 'cats'}:
            value = 1.5
        elif word in {'boss', 'boy', 'boys'}:
            value = 3.0
    elif prev == 'long' and word in {'beach', 'island'}:
        value = 3.0 if word == 'beach' else 2.0
    elif prev == 'major' and word.lstrip('-') == 'league':
        value = 1.1
    elif prev == 'small' and word == 'business':
        value = 2.0
    elif prev == 'general' and word == 'hospital':
        value = -1.6
    elif word in {'公共', '公安', '机关', '总局'}:
        value = 1.0
    elif word == '局' and prev.endswith(('商', '工商')):
        value = 2.8
    elif prev == 'lag' and word == 'rang':
        value = 1.9
    elif prev == 'rang' and word == 'ian':
        value = 2.1
    elif prev.endswith('g') and token[:1].isalpha() and word in {'ian', 'ay', 'y'}:
        if word == 'ian':
            value = 6.0 if prev.endswith('ag') else 0.3
            if prev.endswith('ng'):
                value = 2.0
        elif word == 'ay':
            value = 3.4
        else:
            value = 3.0 if prev.endswith('ag') else 0.8
    elif word == 'agy':
        value = 1.1
    elif word == 'ley' and prev.endswith(('g', 'pres')):
        value = 0.9
    elif prev == '공':
        # Study, industrial complex, corporation, sharing, performance, airport.
        value = {'부': -6.0, '단': -3.4, '사': -2.3,
                 '유': -1.2, '연': -1.8, '항': -0.9}.get(word, 0.0)
    elif prev == '보' and word in {'장', '증'}:
        value = -4.2  # Guarantee / warranty.
    elif token and set(token) == {'·'} and len(token) >= 2:
        value = -2.7

    return (doc, token), value

