"""Government-agency words: fires on the word 'agency' (and 'enforcement' after 'law') etc."""
READS = ()

PHRASES = {
    "agency": 5.0, "agencies": 5.0, "agenc": 4.0,
    "law enforcement": 2.5, "public law": 5.0,
    "public health": 2.3, "public sector": 1.5, "private sector": 1.8,
    "small business": 2.2, "dot leader": 0.0,
}

def step(carry, prefix, upstream):
    t = prefix.position
    tail = "".join(prefix.token_strings[max(0, t - 3): t + 1]).lower()
