"""Detect written 'yu': primarily the Chinese particle 于/於, its compounds,
fish (鱼/魚), and the Roman spelling Yu. Independent 于 is stronger than
common bound prepositions; courage and aptitude complements are also strong.
Doubled middle dots have a separate positive response. A small, case-based
bias describes the otherwise quiet first token of each document.
"""
import re
from functools import lru_cache
from opencc import OpenCC

READS = ()
_simplify = OpenCC('t2s')


@lru_cache(maxsize=16384)
def compound_value(token):
    if not any(c in token for c in '于於鱼魚'):
        return 0.0
    s = _simplify.convert(token.strip())
    traditional = '於' in token
    if token.strip() in ('鱼', '魚'):
        return -3.7 if '魚' in token else -2.75
    if '于' not in s:
        return 0.0
    # 'About' is almost quiet; other common bound prepositions are weak.
    if '关于' in s:
        value = -0.1
    elif any(w in s for w in ('对于', '由于', '属于', '位于', '处于')):
        value = -0.9
    elif s in ('至于', '于是'):
        value = -1.4
    # Dare/be courageous, finally, ease/skill, and time relations.
    elif s in ('敢于', '勇于'):
        value = -5.9
    elif s == '终于':
        value = -3.8
    elif s in ('便于', '易于', '善于', '利于'):
        value = -3.6
    elif s in ('将于', '已于', '并于', '始于', '生于'):
        value = -4.2
    else:
        value = -2.0
    return value * (1.35 if traditional else 1.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    s = token.strip()
    value = compound_value(token)
    if s in ('于', '於'):
        prev = _simplify.convert(previous.strip())
        value = -4.5
        if prev == '关' or prev == '有关':
            value = 0.1
        elif prev == '对':
            value = -0.8
        # Dependence, existence, and comparison complements weaken bare yu.
        elif prev in ('依赖', '基', '受益', '致力', '存在',
                      '高', '低', '小', '大', '少', '近'):
            value = -2.0
        # Unmerged inclination/skill, courage, finally, and excess compounds.
        elif prev in ('乐', '精', '善', '敢', '勇', '终', '过'):
            value = -6.5
        elif previous and not any(ch.isalnum() for ch in previous):
            value = -5.5
        if s == '於':
            value *= 1.1
    elif s == 'Yu':
        value = -2.5 if token.startswith(' ') else -1.3
    elif s == 'yu':
        value = -0.75
    elif s == 'u' and not token.startswith(' ') and tail.endswith('y'):
        word = re.search(r'[A-Za-z]+$', tail)
        value = -1.7 if word and word[0][0].isupper() else -0.8
    elif token == '··':
        value = 1.37
    if not previous and value == 0.0:
        if not s:
            value = -0.21
        elif s.startswith('<|'):
            value = 0.38
        elif s.isascii() and s.istitle():
            value = 0.26
        elif s.isdecimal() or not any(ch.isalnum() for ch in s):
            value = 0.07
        else:
            value = 0.12
    return (doc, (tail + token)[-40:], token), value

"""Approximate multilingual future and conditional marking.

Remember the current word fragment. English modals get small responses;
Romance future/conditional forms get larger ones. Proposed infinitives are
checked with word frequencies, with explicit rules for irregular stems.
Whole forms and separately tokenized endings have different fitted responses.
Nearby French function words help disambiguate homographs.
Chinese/Thai future markers are positive; contracted Japanese progressives
are negative. This is a spelling-based approximation, not a full parser.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Common irregular future stems.
IRREGULAR = {
    'fr': frozenset("""
        aur ser ir dir lir rir fer verr saur devr viendr tiendr recevr
        obtiendr enverr courr mourr acquerr vaudr faudr voudr pourr
    """.split()),
    'es': frozenset("""
        tendr habr podr pondr saldr vendr sabr har dir querr valdr cabr
    """.split()),
    'pt': frozenset("""
        far dir trar
    """.split()),
    'it': frozenset("""
        avr sar dir andr dar far star dovr potr sapr vedr vivr verr
        vorr terr conterr rimarr berr cadr trarr porr tradurr condurr
        produrr morr
    """.split()),
}

# A token may stop partway through a conditional ending (ie or í).
ENDINGS = {
    'fr_future': ('fr', ('ai', 'as', 'a', 'ons', 'ez', 'ont')),
    'fr_conditional': ('fr', ('ais', 'ait', 'ions', 'iez', 'aient', 'ie')),
    'es_future': ('es', ('é', 'ás', 'á', 'emos', 'éis', 'án')),
    'es_conditional': ('es',
        ('ía', 'ías', 'íamos', 'íais', 'ían', 'í', 'ia', 'ias', 'iamos', 'iais', 'ian')),
    'pt_future': ('pt', ('ei', 'ás', 'á', 'emos', 'eis', 'ão')),
    'pt_conditional': ('pt', ('ia', 'ias', 'íamos', 'íeis', 'iam')),
    'it_future': ('it', ('ò', 'ai', 'à', 'emo', 'ete', 'anno')),
    'it_conditional': ('it', ('ei', 'esti', 'ebbe', 'emmo', 'este', 'ebbero')),
}

@lru_cache(maxsize=30000)
def stem_score(stem, language):
    """Familiarity of the proposed infinitive, including spelling changes."""
    if stem in IRREGULAR[language]:
        return 6.0
    if stem == 'ir' and language in ('es', 'pt'):
        return 5.0
    if language == 'fr':
        for tail, verb in (('tiendr', 'tenir'), ('viendr', 'venir')):
            if stem.endswith(tail):
                return zipf_frequency(stem[:-len(tail)] + verb, 'fr')
    if len(stem) < 4:
        if language not in ('es', 'pt') or stem not in {'ser','ver','dar'}:
            return 0.0
    if not stem.endswith('r'):
        return 0.0
    if language in ('es', 'pt'):
        return (zipf_frequency(stem, language)
                if stem.endswith(('ar','er','ir')) else 0.0)
    if language == 'fr':
        regular = (zipf_frequency(stem, 'fr')
                   if stem.endswith(('er','ir')) else 0.0)
        # Infinitives in -re lose their final e before the tense ending.
        re_family = ('endr','ondr','indr','ordr','erdr','oudr','attr','ettr',
                     'rompr','vaincr','crir','vivr','suivr','clur','plair',
                     'tair','nuir','luir','cuir','boir','croir','ir')
        dropped_e = (zipf_frequency(stem + 'e', 'fr')
                     if stem.endswith(re_family) else 0.0)
        return max(regular, dropped_e)
    if language == 'it' and stem.endswith(('er','ir')):
        return max(
            zipf_frequency(stem + 'e', 'it'),
            zipf_frequency(stem[:-2] + 'are', 'it'),
            zipf_frequency(stem[:-3] + 'are', 'it')
            if stem.endswith(('cher','gher')) else 0.0,
            zipf_frequency(stem[:-2] + 'iare', 'it')
            if stem.endswith(('cer','ger')) else 0.0,
        )
    return 0.0


@lru_cache(maxsize=30000)
def conjugation(word):
    """Choose the analysis with the most familiar infinitive/stem."""
    candidates = []
    for form, (language, suffixes) in ENDINGS.items():
        for suffix in suffixes:
            if word.endswith(suffix):
                stem = word[:-len(suffix)]
                familiarity = stem_score(stem, language)
                if familiarity >= 3.0:
                    candidates.append((familiarity, form, stem, suffix))
    return max(candidates, default=None)

AUXILIARIES = {
    "'d": 0.596,
    "'ll": 1.002,
    'could': 0.195,
    'may': 0.12,
    'might': 0.12,
    'shall': 0.436,
    'should': 0.11,
    'will': 1.071,
    'would': 0.671,
    '’d': 0.754,
    '’ll': 1.073,
}

FUTURE_MARKERS = {
    'จะ': 0.278,
    '会': 0.185,
    '将': 0.533,
    '将会': 0.297,
    '將': 0.522,
    '會': 0.42,
