# Responses: whole form, split form, stem already seen, irregular,
# French a/ai ending, nearby French function word.
FORM_RESPONSES = {
    'fr_future': (0.391, 0.741, 2.233, 0.792, 1.441, 5.379),
    'fr_conditional': (0.49, 1.064, 2.439, 0.224, 0.0, 1.96),
    'es_future': (2.611, 4.616, 2.499, -0.414, 0.0, 0.0),
    'es_conditional': (1.403, 4.524, 0.622, 0.556, 0.0, 0.0),
    'pt_future': (4.088, 5.222, 2.862, 0.0, 0.0, 0.0),
    'pt_conditional': (1.578, 2.951, -1.044, 0.0, 0.0, 0.0),
    'it_future': (2.188, 4.432, 1.988, 0.742, 0.0, 0.0),
    'it_conditional': (0.0, 1.962, 0.577, 1.962, 0.0, 0.0),
}

# Nearby closed-class words distinguish French endings from names/nouns.
FRENCH_FUNCTION_WORDS = re.compile(
    r"\b(?:je|tu|il|elle|nous|vous|ils|elles|le|les|des|du|au|aux|"
    r"une|dans|avec|pour|ce|cette|ces|cet|est|sont|qui|pas)\b"
)

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    stripped = token.strip()
    lower = stripped.lower()
    value = AUXILIARIES.get(lower, 0.0)
    if lower in AUXILIARIES:
        if not token[:1].isspace():
            value -= 0.114
        if stripped[:1].isupper():
            value -= 0.188
    value += FUTURE_MARKERS.get(lower, 0.0)

    # Extend a word only when the token begins without a boundary.
    head = re.match(r'^[^\W\d_]+', token)
    if head:
        word = previous + head.group().lower()
        continued = bool(previous)
    else:
        tail = re.search(r'([^\W\d_]+)$', token)
        word = tail.group().lower() if tail else ''
        continued = False

    analysis = conjugation(word) if word else None
    if analysis:
        _, form, stem, suffix = analysis
        whole, split, complete, irregular, a_or_ai, french_hint = FORM_RESPONSES[form]
        value += split if continued else whole
        if continued and len(previous) >= len(stem):
            value += complete
        if stem in IRREGULAR[ENDINGS[form][0]]:
            value += irregular
        if form == 'fr_future' and suffix in ('a','ai'):
            value += a_or_ai
        if form.startswith('fr_'):
            recent = ''.join(
                prefix.token_strings[i]
                for i in range(max(0, prefix.position - 8), prefix.position)
                if prefix.document_ids[i] == document
            )
            if FRENCH_FUNCTION_WORDS.search(recent.lower()):
                value += french_hint

    if lower in ("'t", '’t') and previous in ('won','wouldn','shan'):
        value += 0.545
    if previous.endswith(('て','で')) and token.startswith(('る','ます','た','て')):
        value -= 2.47

    tail = re.search(r'([^\W\d_]+)$', token)
    if not tail:
        word = ''
    elif not token.isalpha():
        word = tail.group().lower()
    return (document, word[-60:]), float(value)

"""A small grammatical approximation to the component's negative verb response.

Join English subwords into the word seen so far. Negative cues include coordinated
verbs, verbs after causatives or adverbs, gerunds after prepositions, and particles
following verbs. Gerunds after determiners or forms of 'be' receive offsets instead.
Rare verbs, Chinese words with verbal dictionary glosses, and internal Arabic
pieces have additional negative cues. These are graded tendencies, not a parser
or a complete reconstruction of the component.
"""
import re
from functools import lru_cache
import regex
import wordnet
import cedict
from wordfreq import zipf_frequency

READS = ()
DETERMINERS = set('a an the this that these those my your his her its our their '
                   'each every some any no another such'.split())
PREPOSITIONS = set('for by of with without after before while when in on at from '
                   'into through upon about'.split())
PRONOUNS = set('i you he she it we they who which'.split())
BE = set('am is are was were be been being'.split())
CAUSATIVES = set('help helps helped helping let lets make makes made'.split())
ADVERBS = set('also now just better further first'.split())
PARTICLES = set('up down out off away over back apart together'.split())

@lru_cache(maxsize=60000)
def word_info(word):
    return (wordnet.parts_of_speech(word), wordnet.base_forms(word, 'verb'),
            zipf_frequency(word, 'en'))

@lru_cache(maxsize=20000)
def chinese_verb(text):
    return any(gloss.startswith('to ') for gloss in cedict.glosses(text))


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, word, previous = (doc, '', '') if first else carry

    # A space starts a word; adjacent letter tokens extend the current word.
    match = re.fullmatch(r'\s*([A-Za-z]+)', text)
    if match:
        if text[:1].isspace() or not word:
            if word:
                previous = word
            word = match[1]
        else:
            word += match[1]
    else:
        if word:
            previous = word
        word = ''
    carry = (doc, word, previous)
    w, p = word.lower(), previous.lower()
    value = -0.1204 if first else 0.0
    if p == 'to':
        value -= 0.0279

    if not word:
        if regex.search(r'\p{Script=Arabic}', text):
            value -= 0.1946 * min(len(text.strip()), 8) / 4
            if text[:1].isspace():
                value += 0.1403
        if regex.search(r'\p{Script=Han}', text) and chinese_verb(text.strip()):
            value -= 0.0335
        return carry, value

    if not text[:1].isspace():
        value -= 0.0040
    pos, bases, frequency = word_info(w)
    if bases:
        if w in bases:
            value -= 0.0052
            if p in PRONOUNS:
                value -= 0.0224
        if frequency < 4:
            value -= 0.0169
        if p in {'and', 'or'}:
            value -= 0.0451
        if p in CAUSATIVES:
            value -= 0.1012
        if p.endswith('ly') or p in ADVERBS:
            value -= 0.0355
        if w.endswith('ed'):
            value += 0.0192
        if w.endswith('ing'):
            if p in PREPOSITIONS:
                value -= 0.1208
            if p in DETERMINERS:
                value += 0.0455
            if p in BE:
                value += 0.0502
    if w in PARTICLES:
        if 'verb' in word_info(p)[0]:
            value -= 0.1377
        if p.endswith('ing'):
            value -= 0.1034
    return carry, value

