# Day, month, year, week, occurrence, time.
# Levels: after a numeral, unnumbered, after "every" (毎).
UNITS = {'日': (-1.5, 5.2, 9.0), '月': (-0.6, 4.0, 7.5),
         '年': (-1.3, 4.3, 9.0), '週': (2.7, 8.5, 13.5),
         '回': (4.2, 6.8, 13.0), '時': (0.6, 5.1, 5.1)}
