RELATIONS = {'場合': 7.1, 'とき': 6.0, '際': 5.0,
             '方': 6.3, 'ほう': 4.2, '方法': 3.7}
FUSED = re.compile(r'(の)?(場合|とき|時|際|方|ほう|人|日|年)'
                   r'(が|は|を|に|には|の|も)?')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 1000, b'')
    _, age, tail = carry
    before = tail.decode('utf-8', 'ignore')
    raw = prefix.token_strings[-1]
    word = raw.strip()
    tail = (tail + prefix.token_bytes[-1])[-160:]
    age = 0 if KANA.search(word) else age + 1
    numbered = bool(NUMBER.search(before.rstrip()))
    value, scale = 0.0, 1.0
    if age <= 40:
        fused = FUSED.fullmatch(word)
        if fused:
            leading, word, particle = fused.groups()
            if leading and word == '方':
                scale *= 0.75
            if particle:
                scale *= (0.75 if word in ('方', 'ほう') else 0.4)
                if word == '方' and particle in ('は', 'も'):
                    scale = 0.5
        if word in UNITS:
            value = UNITS[word][0 if numbered else 1]
            if numbered and word == '日' and '月' in before[-12:]:
                value = -2.3
            if not numbered:
                if before.endswith('毎'):
                    value = UNITS[word][2]
                elif word in ('日', '月', '年') and before.endswith(('今', '昨')):
                    value += 2.3
                if word == '日' and before.endswith(('先', '本', '休')):
                    value = 8.0
                if word == '回' and before.endswith(('初', '前')):
                    value = 8.3
                if word == '時' and before.endswith('当'):
                    value = 7.4
        elif word in RELATIONS:
            value = RELATIONS[word]
            if word == '際' and before.endswith('国'):
                value = 0.5
        elif word in ('最近', '現在', '今回', '朝', '今日'):
            value = 6.2 if word == '今回' else 4.8
        elif word in ('今', '今年', '明日', '昔', '年末'):
            value = 3.0
        elif word in ('夜', '後'):
            value = 1.7
        elif word in ('人', '私', '皆', '人数'):
            value = 0.2 if word == '人' and numbered else 3.0
        elif word in ('結果', '平均', '目的', '数'):
            value = 5.1 if word == '結果' else 2.0
        elif word == '画':
            value = 5.4 if before.endswith('動') else 3.5
        elif word == '真':
            value = 2.8 if before.endswith('写') else 0.6
        elif word in ('写', '撮'):
            value = 1.6
        elif word in ('不', '可能', '全', '完全', '多', '必然'):
            value = -2.1
        elif word in ('ここ', '中心', '下'):
            value = -1.0 if word == '下' else -2.9
        if raw[:1].isspace():
            scale *= 0.5
    # Smaller responses on Korean occasion/method/count counterparts.
    elif word in ('때', '경우', '방법') or raw == ' 회':
        value = 2.0
    return (doc, age, tail), value * scale

"""A sparse approximation of formatting and document-start responses.

Recognize URL punctuation, include directives, selected boilerplate endings and
unfinished emoji prefixes. Otherwise use a small baseline, or a coarse character-
class estimate at a document's first token. Retain only 128 bytes of context and
clear them on document boundaries. The rules omit most small lexical variation.
"""
READS = ()


def response(token, before):
    if token == b'://':
        if before.endswith(b' http'):
            return 1.53
        if before.endswith(b'http'):
            return 1.40
        if before.endswith(b' https'):
            return 1.33
        if before.endswith(b'https'):
            return 1.23
        return 0.20
    if token == b'//' and before.endswith(b':'):
        return 1.50

    # Forum navigation and attribution labels.
    if token == b'permalink':
        return -1.62
    if token == b' permalink':
        return -0.36
    if token == b' Tags' and before.endswith(b'Show'):
        return -2.65
    if token == b' Logged' and before.endswith(b'IP'):
        return -3.57
    if token == b' edited' and before.endswith(b'Last'):
        return -0.74
    if token == b'ed' and before.endswith(b'Author Comment'):
        return -2.74
    if token == b' by' and before.endswith(b'posted'):
        return -0.33

    if token == b' hidden' and before.endswith(b'Comment'):
        return -2.99
    if token == b' timer' and before.endswith(b'Show'):
        return -3.81
    if token == b' source' and before.endswith(b'| edit'):
        return -2.02
    if token == b' :' and before.endswith(b'Last Updated'):
        return -2.97

    # Programming-language declarations and HTML code blocks.
    if token == b' std' and before.endswith(b'namespace'):
        return -2.70
    if token == b' super' and before.endswith(b'use'):
        return -1.65
    if token == b' strict' and before.endswith(b'use'):
        return -0.52
    if token == b'#include':
        return 1.17 if not before else 0.11
    if token in (b'pre', b'code') and before.endswith(b'><'):
        return -3.25
    if token == b'pre' and before.endswith(b'></'):
        return -1.26
    if token == b'pre' and before.endswith(b'<'):
        return -0.43
    if token == b'//\n' and not before:
        return -3.20

    # Formulaic legal and answer-site phrases.
    if token == b' filing' and before.endswith(b'effective'):
        return -3.14
    if token == b' solution' and before.endswith(b'completed'):
        return -5.47

    # Third bytes of incompletely tokenized emoji: flags, nature and animals.
    if len(token) == 1 and before.endswith(b'\xf0\x9f'):
        if token == b'\x87':  # Regional indicator / flag prefix.
            return -1.80
        if token == b'\x8c':  # Weather, plants, earth (U+1F300..1F33F).
            return -4.27
        if token == b'\xa6':  # Animals and food (U+1F980..1F9BF).
            return -2.09
        if token == b'\xa5':  # Food and gestures (U+1F940..1F97F).
            return -3.50
        if token == b'\x90':  # Animal symbols (U+1F400..1F43F).
            return -0.72
        if 0x80 <= token[0] <= 0xbf:
            return -1.20
    # With no preceding context, coarse character classes set the baseline.
    if not before:
        text = token.decode('utf-8', errors='replace')
        word = text.strip()
        if not text.isascii():
            return -0.05
        if text.isspace():
            return 0.24
        if text[:1].isspace():
            return -0.04 if word.istitle() else 0.0
        return 0.24 if word.isdigit() else 0.11
    return 0.0027


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = b'' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_bytes[-1]
    value = response(token, before)
    return (document, (before + token)[-128:]), value

"""GitHub/hub spelling pulses and some opposite Germanic noun fragments.

GitHub is strongest in quotes and at the start of a line; its domain and
folder spellings are weaker. A following .com has a smaller pulse. There
are also positive hub/hack/hook responses, negative het/-heit/-heid
responses, and a negative response to repeated middle dots. Joined
fragments count only at the token where the relevant letters arrive.
