READS = ()


def response(token, previous):
    lower = token.lower()
    prev = previous.lower()
    if 'github' in lower:
        if 'github' not in token:
            return 4.8
        if token.startswith('"'):
            return 12.3
        if previous.endswith('"'):
            return 10.0
        if token.startswith('.github'):
            return 4.3 if previous[-1:].isalnum() else 5.8
        return 8.8 if previous.endswith('\n') else 6.6
    if lower == 'ithub' and prev.endswith('g'):
        return 8.9 if token.islower() else 5.1
    if token == '.com':
        if prev.startswith('.'):
            return 0.0
        if prev == 'ithub':
            return 1.8
        if prev.endswith('ithub'):
            return 2.6 if previous.startswith('"') else 3.4

    word = lower.lstrip(' \t\n.\"\'/_-')
    if word == 'hub':
        if 'H' in token:
            return 6.0
        return 3.1 if token[0].isspace() else 7.5
    if prev.endswith('h') and lower in ('ub', 'ubs'):
        return 7.0
    if word == 'het':
        return -5.8 if token[0].isspace() else -3.8
    if word in ('heit', 'heiten', 'heid', 'heden'):
        return -1.4
    if word == 'heits':
        return -3.0
    # Complete a split -heit or -heid, without reading future letters.
    if prev.endswith('he') and lower in ('it', 'its', 'id', 'ids'):
        return -6.0
    if prev.endswith('h') and lower.startswith(('ed', 'et')):
        return -2.5
    if prev.endswith('h') and lower in ('ack', 'acks', 'acking'):
        return 4.0
    if word in ('hack', 'hacks'):
        return 1.5
    if word in ('hook', 'hooks', 'webhook', 'webhooks'):
        return 0.6
    if len(token) > 1 and set(token) == {'·'}:
        return -1.49
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    return (doc, token), response(token, previous)

