    if ((s.strip() == 'Off' and before.rstrip().endswith('Comments')) or
            (word == 'on' and before.rstrip().endswith('Comments Off'))):
        value = -8.2
    if word == 'tags' and re.search(r'(^|\n|\|) ?$', before):
        value = -5.0 if before.rstrip().endswith('|') else -2.0
    if s == ':' and re.search(r'(^|\n|\|) ?tags$', before, re.I):
        value = -2.0
    if s == 'ged' and re.search(r'(^|\n)Tag$', before):
        value = -7.0
    elif s == 'ged' and re.search(r'(^|\n)#+ Tag$', before):
        value = -3.5
    if not before and s == '#':
        value = -0.5
    # Shrink uncertain text-template matches rather than overstate their pulse.
    return (doc, (before + s)[-180:]), float(0.75 * value)

"""Mostly a spelling-fragment detector for mol, with weaker mel/mul/ml echoes.

It recognizes these fragments within a token or completed across a token
boundary. Molecule words and metric prefixes on mol also respond. Several
competing m-vowel-consonant endings respond negatively. The constants are
training-set estimates, not token-ID lookups. Only Latin, Greek and Cyrillic
spellings are romanized, avoiding accidental matches from other scripts.
Standalone micro signs are distinguished from the letter m before l.
Repeated middle-dot separators get a negative offset. A four-character
suffix carries context and resets at document boundaries; many weak,
context-specific responses are deliberately left unmodeled.
"""
import re
import regex
from anyascii import anyascii

READS = ()
OTHER_SCRIPTS = regex.compile(
    r'[^\p{Script=Latin}\p{Script=Cyrillic}\p{Script=Greek}'
    r'\p{Script=Common}\p{Script=Inherited}]'
)


def ol_completion(text):
    """Strength of the newly completed m-ol fragment, by its extension."""
    if text == 'ol':
        return 10.0
    if re.fullmatch(r'ol(?:e|es|l)', text):
        return 9.5
    if text.startswith('old'):
        return 3.0
    if text.startswith('olecul'):
        return 4.4 if text.endswith('ar') else 3.1
    if text.startswith('olog'):
        return 2.0
    if text == 'olar':
        return 7.8
    return 5.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    micro = carry is not None and carry[0] == doc and carry[2]
    raw = prefix.token_strings[-1]
    text = anyascii(OTHER_SCRIPTS.sub(' ', raw)).lower()
    word = text.strip()
    attached = text and not text[0].isspace()
    value = 0.0

    if re.fullmatch(r'mol(?:e|l)?', word):
        value = 7.6
        if attached and before.endswith(('u', 'm', 'n', 'p')):
            value = 11.8
    elif re.fullmatch(r'molecul(?:e|es|ar)', word):
        value = 4.2 if word.endswith('ar') else 2.3
    elif re.fullmatch(r'mol(?:ly|t)', word):
        value = 3.0
    elif re.fullmatch(r'm[eu]l{1,2}', word):
        value = 1.0 if raw.startswith(' ') else 2.5
        if word.endswith('ll'):
            value = 2.5
    elif re.fullmatch(r'mill(?:s|er)', word):
        value = 1.0
    elif word == 'ml':
        value = 0.7 if raw.startswith(' ') else 2.0
        if raw.strip() == 'mL':
            value = 0.1

    if before.endswith('m') and attached:
        if text.startswith('ol'):
            value = ol_completion(text)
            if text == 'ol' and before.endswith(('mm', 'nm', 'pm')):
                value = 13.0
        elif text.startswith('el'):
            value = 3.0 if len(text) <= 3 else 1.3
        elif text.startswith('ul'):
            value = 4.2 if text == 'ull' else 1.5
        elif text.startswith('uel'):
            value = 1.9
        elif text.startswith('al'):
            value = 0.4
        elif text.startswith('l'):
            value = 4.8 if text == 'l' else 1.5
            if raw == 'L':
                value = 1.5
        elif text == 'ot' and raw.lower() == 'ot':
            value = -4.4
        elif text.startswith(('ont', 'ound', 'ock', 'uck')):
            value = -2.7
        elif text in ('ott', 'oto', 'ok', 'et', 'ets', 'ack', 'ite'):
            value = -2.4 if text == 'ott' else -1.1
        elif text.startswith('t'):
            value = -0.4
        elif text == '1':
            value = 0.5
        if raw.lower().startswith(('ол', 'ель')):
            value = 8.0
        elif raw.lower() == 'от':
            value = -5.5

    if (before.endswith('mo') and attached and text.startswith('l')
            and not raw[0].isupper()):
        value = ol_completion('o' + text)
    if micro and word == 'l':
        value = 0.0
    if raw == 'τ' and before.endswith('ma'):
        value = -4.8
    if raw and set(raw.strip()) == {'·'} and len(raw.strip()) >= 2:
        value = -1.3

    return (doc, (before + text)[-4:], raw.strip() in ('µ', 'μ')), value

"""Predict a start-of-document bias and a few local text constructions.

'Out' is negative, especially as a particle of extraction/action verbs, even
with an intervening object. Joined emphasis markers produce positive values,
particularly on introductory words, p-value letters, and test-directory names.
Java package declarations and parenthesized figure references are also positive.
An initial '12' has a separate negative exception. Other positions are zero.
The magnitudes are training approximations.
"""
import re
from functools import lru_cache
import wordnet

READS = ()


@lru_cache(maxsize=4096)
def verb_strength(word):
    forms = set(wordnet.base_forms(word)) | {word}
    if forms & {'pull', 'pick'}:
        return -4.2
    if forms & {'take', 'bring', 'try', 'draw', 'pay'}:
        return -2.7
    if forms & {'carry', 'drive', 'help', 'cancel', 'test', 'break', 'give'}:
        return -1.6
    if forms & {'print', 'fill', 'mark', 'stick'}:
        return -1.0
    if forms & {'check', 'come', 'get', 'send'}:
        return -0.65
    if forms & {'find', 'figure', 'point', 'turn', 'stand'}:
        return 0.0
    return None


def out_value(tail):
    phrase = re.search(r'[A-Za-z]+(?:\s+[A-Za-z]+){0,2}\s*$', tail)
    words = phrase.group().lower().split() if phrase else []
    for distance, word in enumerate(reversed(words)):
        strength = verb_strength(word)
        if strength is not None:
            return strength * (0.5 ** distance)
    return -0.25


def marker_value(previous, token, tail):
    joined = bool(token) and not token[0].isspace()
    if not joined:
        return -0.1
    double = previous.endswith(('**', '__'))
    if token.isdigit() and re.search(r'(?:^|\n)\*+$', tail):
        return 1.7
    if previous.endswith('**') and token in {'[', '('}:
        return 2.3 if token == '[' else 1.5
    if previous.endswith('__') and token == 'tests':
        return 1.9
    if not token[0].isalpha():
        return 0.0
    if token.lower() in {'note', 'important'}:
        return 2.0
    if double:
        return 0.0
    if token.lower() == 'this':
        return 5.0
    if token in {'The', 'You'}:
        return 2.1
    if token.lower() in {'is', 'only', 'must', 'any'}:
        return 2.5 if token.isupper() else 1.5
    if token == 'P':
        return 2.3
    if token == 'p':
        return 1.5
    if len(token) == 1 and token.isascii() and token.isupper():
        return 1.3
    if token == 'et':
        return 1.0
    return 0.5 if previous.endswith('*') else 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, token, token[-80:], 1), 0.5
    _, previous, tail, position = carry
    value = 0.0
    if position == 1 and previous == '1' and token == '2':
        value = -4.75
    elif token == ' out':
        value = out_value(tail)
    elif previous.endswith(('*', '_')):
        value = marker_value(previous, token, tail)
    elif previous == 'package' and token == ' com':
        value = 2.0 if position == 1 else 0.7
    elif token in {'Fig', 'Figure'} and re.search(r'\(\s*\[$', tail):
        value = 1.5
    return (doc, token, (tail + token)[-80:], position + 1), value

programs.haiku:
"""Layer-1 MLP unit 2302 (its down_proj writes one residual direction).

What it does, in two parts:

1. The first token of a document. Each document in a packed row starts after <|endoftext|>,
   and a row's first token also starts a context with nothing before it. There the unit writes
   a sizeable positive value that depends on how the token looks: about +0.5 for a capitalised
   word, +0.33 for a lowercase word, +0.2 for punctuation, CJK or other symbols, +0.14 for a
   word with a leading space (mid-sentence starts), and ~0 for a stray byte fragment.
2. The Japanese/Chinese word 他 ("other", as in 他店, 他社, 他の), which is clearly negative:
   about -0.5 when Japanese kana appear just before it, about -0.9 in 维他命 (vitamin),
   and about -0.15 when it is the pronoun "he" in Chinese.

Everywhere else it is set to 0. Most positions carry a small diffuse activation that no
simple rule captures, so the program leaves them at 0.
"""
READS = ()


def is_kana(text):
    return any(0x3040 <= ord(ch) <= 0x30FF for ch in text)


def start_value(tok):
    if tok.startswith('<|'):
        return 0.4
    if '�' in tok:
        return 0.0
    if tok.startswith(' '):
        return 0.14
    if tok[:1].isupper():
        return 0.5
    if tok[:1].islower():
        return 0.33
    return 0.2


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, start_value(tok)
    if tok == '他':
        if prefix.token_strings[-2] == '维':
            return None, -0.9
        if is_kana(''.join(prefix.token_strings[-12:-1])):
            return None, -0.5
        return None, -0.15
    return None, 0.0

programs.sol:
"""Sparse Chinese scope, sequencing, and quality vocabulary.

Most tokens get zero. Chinese discourse operators, superlatives and broad
geographical scope get negative values; a few quality/improvement words get
positive values. Several English counterparts have the opposite sign.
Whole-token forms matter: this is not a sentiment rule.
Recent Japanese kana attenuate the Chinese readings. Split 'most recent',
'initial', 'current state', and 'unit' are recognized using the previous text.
Separate rules handle the paired middle-dot token and document-initial
articles, layout, a negative baseline, and the numeric prefixes '12'/'122'.
"""
from functools import lru_cache
import regex
import wordnet
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
HAN = regex.compile(r'\p{Script=Han}')
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')


@lru_cache(maxsize=8192)
def chinese_value(token):
    word = SIMPLIFY.convert(token.strip())
    if word == '另外':  # in addition / another
        return -2.5
    if word == '最早':  # earliest
        return -3.0
    if word == '最后':  # last / finally
        return -1.6
    if word == '最主要':  # most important / primary
        return -1.5
    if word in {'首先', '此外'}:  # firstly / moreover
        return -1.25
    if word == '当然':  # of course
        return -1.1
    if word in {'最', '是最', '最新', '最好', '最初', '最为',
                '最重要', '最重要的', '世界上', '世界上最'}:
        return -1.0
    if word in {'包括', '主要包括'}:
        return -0.9
    if word in {'全国', '在全国'}:  # nationwide
        return -1.1
    if word in {'全球', '同时', '目前'}:  # worldwide / simultaneous / now
        return -0.8
    if word in {'国际', '其中', '最喜欢', '提前'}:  # scope and precedence
        return -0.6
    if word in {'特别', '尤其'}:  # especially
        return -0.55
    if word in {'通常', '其次', '最终', '最高', '最近', '最好的', '的同时'}:
        return -0.35
    if word in {'优秀', '良好', '最佳', '绝佳', '现状', '全覆盖'}:
        # Excellent/good/best, current state, complete coverage.
        return 0.8
    if word == '大型':
        return 1.0
    if word in {'普通', '简单', '特殊'}:  # ordinary / simple / special
        return 0.7
    if word == '增强':  # strengthen
        return 1.3
    if word in {'提升', '改良', '壮', '庞大'}:
        return 0.5
    if word in {'不同', '相似', '类似', '标准'}:  # comparison / standard
        return 0.4
    if word == '表达':  # express
        return 0.6
    if word in {'提高', '改进', '小型', '新型'}:
        return 0.33
    if word == '单元':  # unit
        return 1.8
    return 0.0


@lru_cache(maxsize=8192)
def english_value(token):
    word = token.strip().lower()
    if not word.isascii() or not word.isalpha():
        return 0.0
    if word in {'national', 'international', 'among', 'early', 'latest'}:
        return 0.14
    if word in {'specific', 'specifically', 'specified', 'particular',
                'particularly', 'precise', 'global'}:
        return 0.11
    if word in {'earlier', 'previous', 'final', 'finally', 'eventually'}:
        return 0.08
    if word in {'simple', 'ordinary', 'excellent', 'standard'}:
        return -0.105
    if word in {'different', 'similar'}:
        return -0.08
    roots = set(wordnet.base_forms(word)) | {word}
    if 'enhance' in roots:
        return -0.15
    if roots & {'improve', 'strengthen'}:
        return -0.09
    if 'express' in roots:
        return -0.14
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, age, count, opening = '', 100, 0, ''
    else:
        _, tail, age, count, opening = carry
    age = 0 if KANA.search(token) else age + 1
    value = english_value(token)
    if HAN.search(token):
        value = chinese_value(token)
        word = SIMPLIFY.convert(token.strip())
        previous = SIMPLIFY.convert(tail)
        if word == '近' and previous.rstrip().endswith('最'):
            value = -1.15
        elif word == '初' and previous.rstrip().endswith('最'):
            value = -1.8
        elif word == '初' and previous.endswith('当'):
            value = -0.55
        elif word == '状':
            value = 1.5 if previous.endswith('现') else 0.25
        elif word == '元' and previous.endswith('单'):
            value = 3.0
        elif word == '早':
            value = -0.4
        if age < 20 and word != '状':
            value *= 0.25
    elif token == '··':
        value = -1.64
    if count == 0:
        if value == 0.0:
            value = -0.15
        word = token.strip()
        if word.lower() == 'the':
            value = -0.35 if word == 'The' else -0.6
        elif word.lower() == 'an' or token in {' a', ' a '}:
            value = -0.5
        elif word and set(word) == {'#'}:
            value = -0.5 if len(word) == 1 else -0.4
        elif token.isspace():
            value = -0.67 if '\t' in token else -0.2 if '\n' in token else 0.22
        elif token.isdecimal():
            value = -0.3 if token == '1' else -0.1
        opening = token
    elif count < 3:
        opening += token
        if opening == '12':
            value = -3.156
        elif opening == '122':
            value = -1.264
    return (doc, (tail + token)[-40:], age, count + 1, opening), value
